WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[7522] = { title = "Examine the Vessel", description = "Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!", objectives = "Examine the Vessel of Rebirth and return it to Highlord Demitrian." }
WordHunterWoW_QuestEN[7541] = { title = "Service to the Horde", description = "", objectives = "It will take time for our scholars to study the pendant you brought us.  But for your service to the Horde I would like to offer you a small token.\n\nThank you, <name>.  Your acts bring honor to you, and to us." }
WordHunterWoW_QuestEN[7561] = { title = "Rise, Thunderfury!", description = "You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.You will receive:", objectives = "Present the Dormant Wind Kissed Blade to Highlord Demitrian." }
WordHunterWoW_QuestEN[7562] = { title = "Mor'zul Bloodbringer", description = "<name>, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, <name>.  This quest will be perilous, but a Warlock of your stature does not shy from danger!Upon completion of this quest you will gain:", objectives = "Speak with Mor'zul Bloodbringer at the Altar of Storms in the Burning Steppes.<name>, your delvings into the dark arts are deep. Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer. He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, <name>. This quest will be perilous, but a Warlock of your stature does not shy from danger!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7563] = { title = "Rage of Blood", description = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.Upon completion of this quest you will gain:", objectives = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes." }
WordHunterWoW_QuestEN[7564] = { title = "Wildeyes", description = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Case of Blood to Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes." }
WordHunterWoW_QuestEN[7581] = { title = "The Prison's Bindings", description = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.Upon completion of this quest you will gain:", objectives = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done." }
WordHunterWoW_QuestEN[7582] = { title = "The Prison's Casing", description = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.Upon completion of this quest you will gain:", objectives = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task." }
WordHunterWoW_QuestEN[7583] = { title = "Suppression", description = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, <name>. Because of this, I must recommend that you take companions capable of keeping you alive!You will learn:", objectives = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." }
WordHunterWoW_QuestEN[7601] = { title = "What Niby Commands", description = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.", objectives = "Speak with Impsy in Felwood.If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way." }
WordHunterWoW_QuestEN[7602] = { title = "Flawless Fel Essence", description = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.Upon completion of this quest you will gain:", objectives = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return  to Impsy in Felwood." }
WordHunterWoW_QuestEN[7603] = { title = "Kroshius' Infernal Core", description = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and your minion.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.You will learn:", objectives = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood." }
WordHunterWoW_QuestEN[7604] = { title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to him as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", objectives = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", progress = "Do we have a deal?", completion = "It has been a pleasure doing business with you, <name>!\n\nOn behalf of TB Ltd., I wish you luck in your search for Sulfuras!" }
WordHunterWoW_QuestEN[7621] = { title = "A Warning", description = "", objectives = "Priestess, you are about to undergo a rigorous series of events which shall test all of your abilities.\n\nI suggest that you listen to the story that I have to tell.\n\nBe warned, you must complete this task alone. It is recommended that your allies remain at a distance. Interference by outside agents will result in a most severe punishment.\n\nDestiny has led you and you alone here. Battle with honor. Harness the Light." }
WordHunterWoW_QuestEN[7622] = { title = "The Balance of Light and Shadow", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, <name>.", objectives = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", completion = "Your tenacity and courage are astounding, priestess. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world." }
WordHunterWoW_QuestEN[7623] = { title = "Lord Banehollow", description = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...Upon completion of this quest you will gain:", objectives = "Purchase Shadowy Potions from Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes.\n\nUse the potions to travel through Jaedenar in Felwood, and speak with Lord Banehollow inside the Shadow Hold.Mor'zul says that you want to open a portal to Xoroth. To do that, you'll need Xorothian stardust. That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil. That will require some of my shadowy potions, and that will cost you...Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7624] = { title = "Ulathek the Traitor", description = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar." }
WordHunterWoW_QuestEN[7625] = { title = "Xorothian Stardust", description = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.Upon completion of this quest you will gain:", objectives = "Purchase Xorothian Stardust from Ur'dan inside the Shadow Hold at Jaedenar in Felwood. Bring it to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7626] = { title = "Bell of Dethmoora", description = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.Upon completion of this quest you will gain:", objectives = "Bring 2 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7627] = { title = "Wheel of the Black March", description = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.\n\nAcquire these and bring them to my servant.Upon completion of this quest you will gain:", objectives = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes." }
WordHunterWoW_QuestEN[7628] = { title = "Doomsday Candle", description = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.Upon completion of this quest you will gain:", objectives = "Bring 3 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7629] = { title = "Imp Delivery", description = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!\n\nThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.\n\nI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.Upon completion of this quest you will gain:", objectives = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." }
WordHunterWoW_QuestEN[7630] = { title = "Arcanite", description = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.\n\nTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.\n\nReturn to me when you have the arcanite, and then I'll make the black lodestone.Upon completion of this quest you will gain:", objectives = "Bring 1 Arcanite Bar to Gorzeeki in the Burning Steppes." }
WordHunterWoW_QuestEN[7631] = { title = "Dreadsteed of Xoroth", description = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.\n\nI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.\n\nFortune to you, <name>.  And may the souls of your enemies swiftly find their way into your shard pouch.You will learn:", objectives = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.\n\nProvided item:" }
WordHunterWoW_QuestEN[7632] = { title = "The Ancient Leaf", description = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?", objectives = "Find the owner of the Ancient Petrified Leaf. Good luck, <name>; It's a big world.", progress = "<Vartrus groans.>", completion = "Of course I recognize my own leaves. Look at that! It's in perfect condition.\n\nHow good of you to return it, <class>.\n\nPerhaps you could be of service to us and we to you." }
WordHunterWoW_QuestEN[7633] = { title = "An Introduction", description = "", objectives = "Your diligence and integrity has been noted, <class>.\n\nWe are Ancients: Protectors of this once great forest. Our physical forms were destroyed 10,000 years ago when Archimonde and the Burning Legion marched upon Hyjal. Our spirits, however, remain intact.\n\nThere are tasks that we can offer. Tasks that if completed will open up the secrets of the Ancients to you.\n\nKnow this, should you complete these tasks, merely return to this rock and we shall answer the calling." }
WordHunterWoW_QuestEN[7634] = { title = "Ancient Sinew Wrapped Lamina", description = "Greetings, <class>. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", objectives = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", progress = "Welcome back, young <class>.", completion = "May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten." }
WordHunterWoW_QuestEN[7635] = { title = "A Proper String", description = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.You will receive:", objectives = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood." }
WordHunterWoW_QuestEN[7636] = { title = "Stave of the Ancients", description = "Agents of the Burning Legion are still active in our world, <class>. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, <name>. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.You will receive:", objectives = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself." }
WordHunterWoW_QuestEN[7637] = { title = "Emphasis on Sacrifice", description = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.\n\nYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.\n\nProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.\n\nGo now <name>, time is of the essence.Upon completion of this quest you will gain:", objectives = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it." }
WordHunterWoW_QuestEN[7638] = { title = "Lord Grayson Shadowbreaker", description = "The time has come, <name>, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble <brother/sister>!", objectives = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", completion = "I am glad to see you <name>. I know that you have awaited word as to how to acquire your charger, and now that time has come.\n\nYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you. These are not done as a learning exercise - your stature is beyond simple educational tests. You must save your future companion from the clutches of the evil you have spent your life fighting.\n\nTake heed, your time has come!" }
WordHunterWoW_QuestEN[7639] = { title = "To Show Due Judgment", description = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, <name>.  Your quest continues with him.Upon completion of this quest you will gain:", objectives = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7640] = { title = "Exorcising Terrordale", description = "I have added a pinch of dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer.  You will now use this censer to find areas there that show signs of spiritual turmoil and disturbance.  Look for green auras that permeate the ground as the physical world buckles under the torment of the spirit realm and use the censer to drive out the evil spirits.\n\nWhen you have passed sufficient judgment on the spirits there, you will be ready to proceed.Upon completion of this quest you will gain:", objectives = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7641] = { title = "The Work of Grimand Elmore", description = "A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.\n\nFirst things first, <name> - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with him.Upon completion of this quest you will gain:", objectives = "Speak with Grimand Elmore in Stormwind's Dwarven District.A paladin's charger is nothing more than a pack animal without proper barding for it. The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.\n\nFirst things first, <name> - let's get your barding made. In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore. His work will not be cheap, but his quality is what we seek. Speak with him.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7642] = { title = "Collection of Goods", description = "You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.\n\nOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods.Upon completion of this quest you will gain:", objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind." }
WordHunterWoW_QuestEN[7643] = { title = "Ancient Equine Spirit", description = "Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, <name>.\n\nKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice.Upon completion of this quest you will gain:", objectives = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." }
WordHunterWoW_QuestEN[7644] = { title = "Blessed Arcanite Barding", description = "As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.\n\nIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7645] = { title = "Manna-Enriched Horse Feed", description = "The Silver Hand thought me MAD when I told them that I could make a special horse feed that could nourish spiritual horses.  EVERYONE thought I was mad!  Well, now it's payback time!\n\nI'll make what you need, PALADIN... so-called CHAMPION... but it will cost you.  I need special biscuits - Enriched Manna Biscuits sold only by the Argent Dawn - for this blend.  I also demand, yes DEMAND gold as compensation for the misery I have endured!\n\nShow me the sacrifice you tout so much, PALADIN.You will receive:", objectives = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities." }
WordHunterWoW_QuestEN[7646] = { title = "The Divination Scryer", description = "We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.\n\nThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the shadows!Upon completion of this quest you will gain:", objectives = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7647] = { title = "Judgment and Redemption", description = "Take this satchel - in it are the items you will need for your task.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits that must be judged.  Use your judgments wisely during this trial - they will prove more potent than you realize.  After the spirits, the death knight will appear; defeat him and reclaim the lost soul of the charger.  Only then <name>, will you be able to redeem it and place your barding upon your new steed!\n\nGood luck!Upon completion of this quest you will gain:", objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." }
WordHunterWoW_QuestEN[7648] = { title = "Grimand's Finest Work", description = "<Grimand wipes sweat from his brow, beaming with a sense of pride.>\n\nThere you are, my friend.  This is some of my finest work - as good as the barding I personally made for Lord Shadowbreaker when he went for his own charger.  I thank you for your trust in me to provide for you the best.\n\nNo doubt Grayson will want to see the work for himself as well.  Take your barding to him, and give him my thanks for his honorable business.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection." }
WordHunterWoW_QuestEN[7649] = { title = "Enchanted Thorium Platemail: Volume I", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." }
WordHunterWoW_QuestEN[7650] = { title = "Enchanted Thorium Platemail: Volume II", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." }
WordHunterWoW_QuestEN[7651] = { title = "Enchanted Thorium Platemail: Volume III", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe." }
WordHunterWoW_QuestEN[7652] = { title = "A Blue Light Bargain", description = "", objectives = "Aright, mister, I got a hot deal for ya.\n\nI'm lookin' to offload some of these here Imperial plate armor recipes and need someone willing to take on the burden. All I want in exchange is some thorium bars. Sound good?" }
WordHunterWoW_QuestEN[7653] = { title = "Imperial Plate Belt", description = "", objectives = "For the belt plans, I'll be needin' 10 thorium bars.", progress = "For the belt plans, I'll be needin' 10 thorium bars.", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
WordHunterWoW_QuestEN[7654] = { title = "Imperial Plate Boots", description = "", objectives = "For the boot plans, I'll be needin' 20 thorium bars. Yep, 20. Are you gonna cry? Would you like a hanky?\n\n<Derotain laughs.>", progress = "For the boot plans, I'll be needin' 20 thorium bars. Yep, 20. Are you gonna cry? Would you like a hanky?\n\n<Derotain laughs.>", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
WordHunterWoW_QuestEN[7655] = { title = "Imperial Plate Bracer", description = "", objectives = "For the bracer plans, I'll be needin' 10 thorium bars.\n\nAre you alright, sonny? Yer getting' all red.", progress = "For the bracer plans, I'll be needin' 10 thorium bars.\n\nAre you alright, sonny? Yer getting' all red.", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
WordHunterWoW_QuestEN[7656] = { title = "Imperial Plate Chest", description = "", objectives = "For the chest piece plans, I'll be needin' 30 thorium bars.\n\nOh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life's fair.", progress = "For the chest piece plans, I'll be needin' 30 thorium bars.\n\nOh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life's fair.", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
WordHunterWoW_QuestEN[7657] = { title = "Imperial Plate Helm", description = "", objectives = "Just hand over 25 thorium bars and the helm plans are yers.", progress = "Just hand over 25 thorium bars and the helm plans are yers.", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
WordHunterWoW_QuestEN[7658] = { title = "Imperial Plate Leggings", description = "", objectives = "Just hand over 30 thorium bars and the leg plans are yers.\n\nI know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.", progress = "Just hand over 30 thorium bars and the leg plans are yers.\n\nI know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.", completion = "A pleasure doin' business with ya.\n\nAnd <name>, wipe that look of disgust off yer face." }
