WordHunterWoW_QuestEN[7809] = { title = "A Donation of Mageweave", description = "", objectives = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Gnomeregan Exiles, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Gnomeregan Exiles, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[7810] = { title = "Arena Master", description = "There must be more to being a master of the arena than this!\n\nPerhaps the Pirate who runs the event at Gurubashi will know!", objectives = "Speak with Short John Mithril in the Stranglethorn Arena.\n\nProvided item:", completion = "Arr Me Hearty!   Gaining one Trinket be not enough to make ye master of the Arena!    Now tis the time to truly prove your steel." }
WordHunterWoW_QuestEN[7811] = { title = "A Donation of Runecloth", description = "", objectives = "<name>, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.\n\nIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.", progress = "<name>, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.\n\nIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.", completion = "Fantastic - these will go right to use, I assure you. Thank you again for your assistance! We'd certainly be lost without you.\n\nWith all the donations you've made, I would certainly process any additional runecloth donations you care to make in the future. Just be sure to check in with me, and I'll personally make sure that your good deeds won't go unrecognized!" }
WordHunterWoW_QuestEN[7812] = { title = "Additional Runecloth", description = "", objectives = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Gnomeregan Exiles.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", progress = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Gnomeregan Exiles.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "<name> - without heroes like you working on behalf of the gnomes, we'd surely suffer. Thank you for your continued efforts!" }
WordHunterWoW_QuestEN[7813] = { title = "A Donation of Wool", description = "", objectives = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[7814] = { title = "A Donation of Silk", description = "", objectives = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[7815] = { title = "Snapjaws, Mon!", description = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.\n\nDo me and the people of Revantusk Village a service and kill em, mon.\n\nKill the whole lot of em!", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.", completion = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job." }
WordHunterWoW_QuestEN[7816] = { title = "Gammerita, Mon!", description = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\n\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.", progress = "Did you get it yet?", completion = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up." }
WordHunterWoW_QuestEN[7817] = { title = "A Donation of Mageweave", description = "", objectives = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Undercity, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Undercity, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
