WordHunterWoW_QuestEN[7819] = { title = "Additional Runecloth", description = "", objectives = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Undercity.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", progress = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Undercity.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "<name> - without heroes like you working on behalf of the Forsaken, we'd surely suffer. Thank you for your continued efforts!" }
