WordHunterWoW_QuestEN[7827] = { title = "A Donation of Silk", description = "", objectives = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[7828] = { title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, <race>. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 5 Silvermane Stalkers and 5 Silvermane Howlers. Return to him once the task is complete.\n\nMarkhor mentioned that the wolves hide in the wilds of the Hinterlands.", completion = "A job well done, <race>. The Revantusk thank you for your contribution." }
WordHunterWoW_QuestEN[7829] = { title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, <race>. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Savage Owlbeasts. Return to him once the task is complete.\n\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.", completion = "You have proven a worthy ally to the Revantusk, <name>. Well done." }
WordHunterWoW_QuestEN[7830] = { title = "Avenging the Fallen", description = "The filth that calls itself Wildhammer trains gryphon to slay troll. Horrible, I know, but worry not, justice will soon be meted out.\n\nFor now, I want you to focus on eradicating the elder gryphons of the region. They are known as Skylords.\n\nSlay one and return to me with its plume.", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\n\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.", progress = "The Razorbeak Skylord is a much rarer breed of gryphon: One responsible for mating and creating murderous offspring.", completion = "<Markhor examines the plume.>\n\nI wonder how many of our hunters this beast devoured before you brought it to justice." }
WordHunterWoW_QuestEN[7831] = { title = "A Donation of Mageweave", description = "", objectives = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Orgrimmar, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Orgrimmar, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[7832] = { title = "Additional Runecloth", description = "", objectives = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Orgrimmar.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", progress = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Orgrimmar.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "<name> - without heroes like you working on behalf of Orgrimmar, we'd surely suffer. Thank you for your continued efforts!" }
