WordHunterWoW_QuestEN[7837] = { title = "Additional Runecloth", description = "", objectives = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Darkspear Trolls.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", progress = "Greetings once again, <name>! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Darkspear Trolls.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "<name> - without heroes like you working on behalf of the trolls, we'd surely suffer. Thank you for your continued efforts!" }
WordHunterWoW_QuestEN[7838] = { title = "Arena Grandmaster", description = "", objectives = "Avast Lubber!   Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!   Arrrr!", progress = "Avast Lubber!   Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!   Arrrr!", completion = "Much blood have you spilt on the Arena floor and I be glad to name you Grandmaster of the Arena!" }
WordHunterWoW_QuestEN[7839] = { title = "Vilebranch Hooligans", description = "Vilebranch scum invaded our village and stole my tools! I have backup tools but the set they stole was a gift given to me by a kind hearted gnome that saved my life when I was a young orc.\n\nI want those tools back, <name> - they mean the world to me.\n\nMarkhor reported that the tools were spotted near the Agol'watha and Shaol'watha temples.\n\nThose temples are in the northeastern region of the Hinterlands.\n\nRecover my tools!", objectives = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.\n\nYou recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock.", progress = "Watch out for the Vilebranch trolls of the region, <name>. They are ruthless, murderous filth.", completion = "My tools! You found them! Oh glorious day! Thank you, <name>." }
WordHunterWoW_QuestEN[7840] = { title = "Lard Lost His Lunch", description = "Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.", objectives = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\n\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", progress = "<Lard rubs his enormous belly.>\n\nLard so hungry.", completion = "<Lard takes the huge haunch of meat from you and stuffs it in his face.>\n\nDis hit da spot! Tanks little one.\n\nLard make you special picnic basket for help Lard." }
WordHunterWoW_QuestEN[7841] = { title = "Message to the Wildhammer", description = "The Wildhammer be striking up deals with our enemies, forgin' new alliances. This time, they be workin' with the high elves, mon.\n\n<Otho spits.>\n\nWe be needin' to send those Wildhammer dwarves a message - a message in the blood of our enemies. Slaughter every Highvale high elf that you come across, leave their bodies as a warnin'.\n\nNever mess with trolls!", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 8 Highvale Scouts, 5 Highvale Outrunners, 5 Highvale Rangers and 2 Highvale Marksman. Return to him when this task is complete.\n\nYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.", completion = "It be lookin' like the Revantusk are forgin' new alliances as well, mon! You done good." }
WordHunterWoW_QuestEN[7842] = { title = "Another Message to the Wildhammer", description = "They say the Wildhammer and gryphon are as close to each other as troll and mate. Disgusting, but we be able to use this to our advantage, mon. We send them another message.\n\nKill all the gryphons you see in the Hinterlands and collect a long elegant feather! From this we make the final message.", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 1 Long Elegant Feather from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\n\nGryphons are known to inhabit every region of the Hinterlands.", progress = "The last message gonna scare them off for sure. Either that or make them very, very angry.", completion = "Oh, mon, this gonna be good. One more step to go and Wildhammer see that they can't mess with troll!" }
WordHunterWoW_QuestEN[7843] = { title = "The Final Message to the Wildhammer", description = "<Otho hands you a long, blood drenched spear, wrapped in several gryphon feathers.>\n\nYou take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business! Come back when you do this. Hopefully you come back alive.", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.\n\nBeware of angry Wildhammer dwarves and unruly members of the Alliance.", completion = "I wish I coulda been there to see the look on their faces, mon. Are they packing up their bags? Leavin' town?\n\nYou done good, <name>. Real good. Otho reward you with the big mojo." }
WordHunterWoW_QuestEN[7844] = { title = "Cannibalistic Cousins", description = "Three different tribes of trolls inhabit the Hinterlands, <name>. That is about as far as the similarities between the tribes extends: We are all trolls and we live in the Hinterlands.\n\nThe Vilebranch - aptly named - are a depraved lot; feeding on other trolls and humanoids.\n\nIf Zul'jin were here, he would have destroyed the whole lot of them with a flick of his wrist - alas, Zul'jin has not yet returned and we are left to our own devices.\n\nIt is up to you to destroy the filth of the region!", objectives = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 6 Vilebranch Scalpers and 2 Vilebranch Soothsayers. Return to her when this task is complete.\n\nYayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.", completion = "Well done, <class>. Zul'jin himself could not have done a better job!" }
WordHunterWoW_QuestEN[7845] = { title = "Kidnapped Elder Torntusk!", description = "My mate was taken by Vilebranch savages in a bold midnight raid on our village. Our spies have told me that he is still alive and being held prisoner atop Jintha'alor. The Vile Priestess Hexx is said to be preparing him for a sacrifice to the faceless blood God, Hakkar.\n\nYou must save him, <name>! Our village could not stand a loss this great.", objectives = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\n\nYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.My mate was taken by Vilebranch savages in a bold midnight raid on our village. Our spies have told me that he is still alive and being held prisoner atop Jintha'alor. The Vile Priestess Hexx is said to be preparing him for a sacrifice to the faceless blood God, Hakkar.\n\nYou must save him, <name>! Our village could not stand a loss this great.", completion = "You must act quickly, <name>. Surely the guards have been alerted to your presence." }
WordHunterWoW_QuestEN[7846] = { title = "Recover the Key!", description = "The key to my bindings is held by Hitah'ya the Keeper. She is in the nearby cave. Be careful, <class>, for she is guarded well.\n\nKill her and bring the key back to loosen my shackles. Only then will I be free to return home.", objectives = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key.", progress = "You must hurry!", completion = "Freedom at last! Thank you, <name>. Revantusk will know your deeds!" }
WordHunterWoW_QuestEN[7847] = { title = "Return to Primal Torntusk", description = "Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you.", objectives = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you.", completion = "You have done the Revantusk a great service, <name>! We owe you a great debt of gratitude." }
WordHunterWoW_QuestEN[7848] = { title = "Attunement to the Core", description = "Rifts stir, tear, and collapse all around us, {race}. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", objectives = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", progress = "You must attune your soul with the Molten Core before access is granted.", completion = "I am now able to transport you to the Molten Core. Ask and it shall be done." }
WordHunterWoW_QuestEN[7849] = { title = "Separation Anxiety", description = "Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch.\n\nSadly, he was not fated to live and was given a swift, brutal execution; his remains fed to the oozes and wolves of the Vilebranch.\n\nIt is too late to save his life but not too late to save his soul. Recover his remains, <name>.", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.\n\nMarkhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", progress = "When I have his remains, I shall take them to Yayo'jin and have them prepared for a proper burial.", completion = "My dearest brother, how I will miss you...\n\nThank you for your assistance, <name>. You are truly a hero in my eyes." }
WordHunterWoW_QuestEN[7850] = { title = "Dark Vessels", description = "The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx.\n\nThroughout Jintha'alor you will find dark vessels of tainted blood. The vessels radiate the foul magic of the faceless blood God, empowering the Vilebranch and also driving them to madness.\n\nSteal those vessels and return them to me so that I may remove the taint and ultimately loosen the grip of the blood God.", objectives = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 5 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", progress = "Be cautious in battling the Vilebranch, <name>. Their minds are clouded - they fight to the death.", completion = "The dark energy that compels the Vilebranch has been lifted - for now. We must remain ever vigilant in our battle against evil, as even if the Vile Priestess is destroyed, another soon takes her place." }
WordHunterWoW_QuestEN[7861] = { title = "Wanted: Vile Priestess Hexx and Her Minions", description = "By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice!\n\nA grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard.", objectives = "You have been ordered to slay Vile Priestess Hexx and 5 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\n\nVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", completion = "A crippling blow to the Vilebranch, indeed. You shall be richly rewarded, <name>." }
WordHunterWoW_QuestEN[7862] = { title = "Job Opening: Guard Captain of Revantusk Village", description = "With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open. If you are interested in becoming Captain of the Guard for Revantusk, complete the following tasks and submit your application to Primal Torntusk:\n\nExterminate Vilebranch Berserkers.\n\nExterminate Vilebranch Shadow Hunters.\n\nExterminate Vilebranch Blood Drinkers.\n\nExterminate Vilebranch Soul Eaters.", objectives = "You have been tasked with the decimation of 5 Vilebranch Berserkers, 3 Vilebranch Shadow Hunters, 3 Vilebranch Blood Drinkers, and 2 Vilebranch Soul Eaters.\n\nShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", completion = "You are indeed a worthy candidate for the new position, <name>. Accept this trinket as a token of our appreciation for your hard work. I will be reviewing all applications next year." }
WordHunterWoW_QuestEN[7863] = { title = "Sentinel Basic Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Warsong Gulch.\n\nAs you continue to prove yourself inside the Gulch, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored." }
