WordHunterWoW_QuestEN[7871] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[7872] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[7873] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[7874] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, <race>. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, <name>, and you will be rewarded.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp." }
WordHunterWoW_QuestEN[7875] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, <race>. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, <name>, and you will be rewarded.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp." }
WordHunterWoW_QuestEN[7876] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, <race>. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, <name>, and you will be rewarded.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp." }
WordHunterWoW_QuestEN[7877] = { title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", objectives = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", completion = "You open the chest to find..." }
WordHunterWoW_QuestEN[7881] = { title = "Carnival Boots", description = "", objectives = "We at the Darkmoon Faire do much walking.  We walk from one faire site to another... in fact, you'll never see us sitting down on the job!  So it is no surprise that we wear out quite a lot of boots!  We need boots that are both durable and stylish, and embossed leather boots fit that bill rather well.\n\nYou!  You're a leatherworker; make me embossed leather boots and I'll give you a Darkmoon Faire ticket for the work.", progress = "We at the Darkmoon Faire do much walking.  We walk from one faire site to another... in fact, you'll never see us sitting down on the job!  So it is no surprise that we wear out quite a lot of boots!  We need boots that are both durable and stylish, and embossed leather boots fit that bill rather well.\n\nYou!  You're a leatherworker; make me embossed leather boots and I'll give you a Darkmoon Faire ticket for the work.", completion = "Thank you, <name>.  These are quite well made.  The craftsmanship is top notch!  Here is a Darkmoon Faire ticket... enjoy, sir." }
WordHunterWoW_QuestEN[7882] = { title = "Carnival Jerkins", description = "", objectives = "Our Faire workers do more than sweep trash and hammer spikes!  They also help guard the carnival as it travels, and to that end they are always needing good sturdy armor jerkins.\n\nIf you make some tough leather armor and bring it to me, then I'll make sure it gets to the right people.  I'll also get you some Darkmoon Faire tickets as trade.", progress = "Our Faire workers do more than sweep trash and hammer spikes!  They also help guard the carnival as it travels, and to that end they are always needing good sturdy armor jerkins.\n\nIf you make some tough leather armor and bring it to me, then I'll make sure it gets to the right people.  I'll also get you some Darkmoon Faire tickets as trade.", completion = "Ah, you brought the jerkins.  Splendid.  What animal's skin did you use to make these, may I ask?  The stitch-work is very well done, and the texture of the leather has a rugged style to it.  I can tell you are a craftsman of skill!\n\nThank you, <name>, and here are your tickets." }
WordHunterWoW_QuestEN[7883] = { title = "The World's Largest Gnome!", description = "", objectives = "Yebb Nebblegear is looking to add more talent to his show, and he's searching far and wide for the world's largest gnome.  Do you know any gnomes of considerable size?\n\nWell before he finds the gnome, he wants to have its costume ready.  I think a barbaric harness would be a good foundation for the costume; can you make some harnesses and bring them to me?  Do that, and I'll have a stack of Darkmoon Faire tickets for you...", progress = "Yebb Nebblegear is looking to add more talent to his show, and he's searching far and wide for the world's largest gnome.  Do you know any gnomes of considerable size?\n\nWell before he finds the gnome, he wants to have its costume ready.  I think a barbaric harness would be a good foundation for the costume; can you make some harnesses and bring them to me?  Do that, and I'll have a stack of Darkmoon Faire tickets for you...", completion = "Oh dear, these are quite large!!  I can't imagine finding a gnome that would fit snugly into them, but not to worry - if the gnome we find is not big enough, I can make adjustments to his costume.\n\nMany thanks, <name>.  Here are the tickets I promised you." }
WordHunterWoW_QuestEN[7884] = { title = "Crocolisk Boy and the Bearded Murloc", description = "", objectives = "Yebb is working on other attractions for his zoo, including wet, swampy abodes for a boy raised by crocolisks, and perhaps for a murloc.  We will need nice, water-tight leggings so we won't get waterlogged during prop-ups and tear-downs.  For that job, I think turtlescale leggings will do the trick.\n\n<name>, can you make those leggings?  If you do, then a fat stack of Darkmoon Faire tickets will be your reward...", progress = "Yebb is working on other attractions for his zoo, including wet, swampy abodes for a boy raised by crocolisks, and perhaps for a murloc.  We will need nice, water-tight leggings so we won't get waterlogged during prop-ups and tear-downs.  For that job, I think turtlescale leggings will do the trick.\n\n<name>, can you make those leggings?  If you do, then a fat stack of Darkmoon Faire tickets will be your reward...", completion = "Great, you made them!  These will do nicely... I just hope I won't be the one to clean the crocolisk cage when the time comes.  Those beasts can be rather beastly, don't you think?\n\nHere are your tickets, <name>.  Enjoy them, and enjoy your stay at the Darkmoon Faire!" }
WordHunterWoW_QuestEN[7885] = { title = "Armor Kits", description = "", objectives = "You might not realize this, but running a traveling carnival is costly!  Everything wears down so fast it's a wonder we can turn a profit.\n\nBecause of all those hidden costs, we're always looking for ways to maintain our equipment as cheaply as possible.  Our tents, for instance, tear regularly but I've found that leather armor kits make great patches.  Can you find and bring me some armor kits? That'll save us a bundle!  Do that, and I have a fistful of Darkmoon Faire tickets for you...", progress = "You might not realize this, but running a traveling carnival is costly!  Everything wears down so fast it's a wonder we can turn a profit.\n\nBecause of all those hidden costs, we're always looking for ways to maintain our equipment as cheaply as possible.  Our tents, for instance, tear regularly but I've found that leather armor kits make great patches.  Can you find and bring me some armor kits? That'll save us a bundle!  Do that, and I have a fistful of Darkmoon Faire tickets for you...", completion = "Great!  This will work great!  I just noticed a rip in a tent over yonder, and one of these armor kits is just what I need to patch it up!\n\nThank you very much, <name>.  These armor kits will save us a ton in repair costs.  Here are your tickets - you deserve them!" }
WordHunterWoW_QuestEN[7886] = { title = "Talismans of Merit", description = "", objectives = "" }
WordHunterWoW_QuestEN[7887] = { title = "Talismans of Merit", description = "", objectives = "" }
WordHunterWoW_QuestEN[7888] = { title = "Talismans of Merit", description = "", objectives = "" }
WordHunterWoW_QuestEN[7889] = { title = "Coarse Weightstone", description = "", objectives = "It takes a lot of work to be the strongest woman alive!  My weight set is getting too light and if I'm to stay fit then I'll need more weights!\n\nDo you think you could bring me some weight stones?  If you do, then I'll give you a Darkmoon Faire ticket.", progress = "It takes a lot of work to be the strongest woman alive!  My weight set is getting too light and if I'm to stay fit then I'll need more weights!\n\nDo you think you could bring me some weight stones?  If you do, then I'll give you a Darkmoon Faire ticket.", completion = "Great!  These will work great!  They're not too heavy, but not too light either.  They're perfect for building muscle mass!\n\nThanks much, <name>.  Here's your Darkmoon Faire ticket!" }
WordHunterWoW_QuestEN[7890] = { title = "Heavy Grinding Stone", description = "", objectives = "To help with my workout, I like to fit a staff between heavy grinding stones, then lift the staff over my head.  It isn't easy, but being the strongest woman in the world, like I am, can't be earned sitting down!\n\nCan you help me?  I need more grinding stones - bring me some and I'll trade Darkmoon Faire tickets for them.", progress = "To help with my workout, I like to fit a staff between heavy grinding stones, then lift the staff over my head.  It isn't easy, but being the strongest woman in the world, like I am, can't be earned sitting down!\n\nCan you help me?  I need more grinding stones - bring me some and I'll trade Darkmoon Faire tickets for them.", completion = "You brought the stones!  And they're heavy!  I can already feel my muscles getting bigger.  Thanks <name>!\n\nHere, take these tickets, and be sure not to eat too many sweets while you're at the faire.  A big strong <class> like you needs to keep himself in fighting shape!" }
WordHunterWoW_QuestEN[7891] = { title = "Green Iron Bracers", description = "", objectives = "I'm working on a new costume, for when I have my own booth as the strongest woman alive!  Right now I'm looking for some bracers I can wear.  They can't cover much because people want to see my muscles, but I still want to flash a little color, you know?\n\nHow about green iron bracers, <name>?  Can you make me green iron bracers?  If you can, then I have a whole bunch of Darkmoon Faire tickets for you.", progress = "I'm working on a new costume, for when I have my own booth as the strongest woman alive!  Right now I'm looking for some bracers I can wear.  They can't cover much because people want to see my muscles, but I still want to flash a little color, you know?\n\nHow about green iron bracers, <name>?  Can you make me green iron bracers?  If you can, then I have a whole bunch of Darkmoon Faire tickets for you.", completion = "Yes!  These are exactly what I need!  Such a lovely color, and they still leave my arms bare so you can see how strong they are!  Perfect!\n\nHere you are, <name>.  Here are your tickets - enjoy!" }
WordHunterWoW_QuestEN[7892] = { title = "Big Black Mace", description = "", objectives = "For my act as the strongest woman alive, I plan to accept items from the audience and smash them with a big, black mace!\n\nCan you make me a big black mace, <name>?", progress = "For my act as the strongest woman alive, I plan to accept items from the audience and smash them with a big, black mace!\n\nCan you make me a big black mace, <name>?", completion = "Ah, perfect!  This mace has a big, heavy head on it.  I bet I could smash just about anything with it.  I just hope I don't break it along with whatever I swing it against!\n\nHere are your tickets, <name>.  Enjoy your stay at the faire!" }
WordHunterWoW_QuestEN[7893] = { title = "Rituals of Strength", description = "", objectives = "<name>, in my quest to become the strongest woman alive, I have traveled the world and learned muscle building secrets from distant weight masters, strength gurus, and ancient manuals.  I now know forbidden exercises that would kill the weak and cripple the uninitiated!\n\nThese feats of strength and conditioning require training with the densest of grinding stones.  <name>, can you find or make some grinding stones and bring them to me?  I'll give you tickets if you do...", progress = "<name>, in my quest to become the strongest woman alive, I have traveled the world and learned muscle building secrets from distant weight masters, strength gurus, and ancient manuals.  I now know forbidden exercises that would kill the weak and cripple the uninitiated!\n\nThese feats of strength and conditioning require training with the densest of grinding stones.  <name>, can you find or make some grinding stones and bring them to me?  I'll give you tickets if you do...", completion = "Thank you, <name>.  I will use these stones in a strength-gaining ritual I learned from an ancient tablet in the deepest jungles of Stranglethorn.\n\nIt is said that she who performs this sacred rite correctly will have the strength and endurance of ten Tauren!" }
WordHunterWoW_QuestEN[7894] = { title = "Copper Modulator", description = "", objectives = "Yebb is developing a new attraction for the Zoo Bizarre, one that will drive people crazy with wonder, and delight!  But it will take a lot of work, and a lot of materials...\n\nThat includes copper modulators.  We need lots of modulators for the mechanical parts of the attraction.  Bring me copper modulators and I'll trade for them with a Darkmoon Faire ticket.", progress = "Yebb is developing a new attraction for the Zoo Bizarre, one that will drive people crazy with wonder, and delight!  But it will take a lot of work, and a lot of materials...\n\nThat includes copper modulators.  We need lots of modulators for the mechanical parts of the attraction.  Bring me copper modulators and I'll trade for them with a Darkmoon Faire ticket.", completion = "Aha!  The modulators!  Superb!\n\nI can't tell you exactly what we're building, but these will be invaluable for its construction.  I am in your debt, <name>, but please, take this Darkmoon Faire ticket as a token of my appreciation." }
WordHunterWoW_QuestEN[7895] = { title = "Whirring Bronze Gizmo", description = "", objectives = "My new booth will be a sight to see, yes sir!  A sight to see, and... for a lucky few, to touch!\n\nI can already hear the whirring bronze gizmos singing their song of mechanical rapture as patrons step to my booth and test their skill!\n\nAh... now I need the gizmos themselves to bring my dream closer to fruition.  Please, <name>, bring me whirring bronze gizmos... and Darkmoon Faire tickets will be yours!", progress = "My new booth will be a sight to see, yes sir!  A sight to see, and... for a lucky few, to touch!\n\nI can already hear the whirring bronze gizmos singing their song of mechanical rapture as patrons step to my booth and test their skill!\n\nAh... now I need the gizmos themselves to bring my dream closer to fruition.  Please, <name>, bring me whirring bronze gizmos... and Darkmoon Faire tickets will be yours!", completion = "You brought the gizmos!  Wonderful!  Even now I can hear their buzzing, whirring chorus in my mind!  Oh, when this booth is ready it will be the wonder of the world, mark me!\n\nHere are your tickets, <name>.  And please enjoy your stay at the Faire!" }
WordHunterWoW_QuestEN[7896] = { title = "Green Fireworks", description = "", objectives = "When I finally get this booth up and running, I'll want to advertise!  And what better way is there to advertise than with fireworks?\n\nWell, some might think that the smell of a cauldron, churning with the boiling heads of your foes is better for drawing crowds, but... we're in mixed company.  So fireworks it will have to be!\n\nBring me green fireworks, <name>, and I have a big fistful of Darkmoon Faire tickets for you.", progress = "When I finally get this booth up and running, I'll want to advertise!  And what better way is there to advertise than with fireworks?\n\nWell, some might think that the smell of a cauldron, churning with the boiling heads of your foes is better for drawing crowds, but... we're in mixed company.  So fireworks it will have to be!\n\nBring me green fireworks, <name>, and I have a big fistful of Darkmoon Faire tickets for you.", completion = "You brought the fireworks.  Wonderful work, <name>!  I can't wait to light these and tell the world that my booth is ready to go!  I must still wait, quite a long time I'm afraid, but... I'll be ready when I'm ready, yes?\n\nHere are the tickets, <name>.  Enjoy yourself!" }
WordHunterWoW_QuestEN[7897] = { title = "Mechanical Repair Kits", description = "", objectives = "The biggest reason I can't open up my booth is that... everything's broken!  I need mechanical repair kits to fix all this stuff!\n\nCan you bring me those kits, <name>?  I'll trade you... kits for Darkmoon Faire tickets.  What do you say?", progress = "The biggest reason I can't open up my booth is that... everything's broken!  I need mechanical repair kits to fix all this stuff!\n\nCan you bring me those kits, <name>?  I'll trade you... kits for Darkmoon Faire tickets.  What do you say?", completion = "Thank you!  Now I can get to fixing things.\n\nIt's going to take a lot of repair kits and a lot of late nights to get everything in working order.  Sometimes I think it'd be better to get back to my roots and restart my career as a headhunter, but... the Faire has been good to me.\n\nTake these tickets, <name>, and have fun!" }
WordHunterWoW_QuestEN[7898] = { title = "Thorium Widget", description = "", objectives = "Yebb Nebblegear, like me, is working on a future attraction.  So amazing is this attraction, says Nebb, that it will draw folks from across the world... and it will make us all very, very rich!\n\nHe says he needs thorium widgets for its construction, and wants me to collect them for him.  So what do you say, <name>?  Do you know where to get thorium widgets?  If you're an engineer, can you make them?  Do you want to trade them for Darkmoon Faire tickets?", progress = "Yebb Nebblegear, like me, is working on a future attraction.  So amazing is this attraction, says Nebb, that it will draw folks from across the world... and it will make us all very, very rich!\n\nHe says he needs thorium widgets for its construction, and wants me to collect them for him.  So what do you say, <name>?  Do you know where to get thorium widgets?  If you're an engineer, can you make them?  Do you want to trade them for Darkmoon Faire tickets?", completion = "Ah, thank you, <name>!  Yebb will enjoy these widgets.  I don't know what he has planned for them, but Yebb's a clever little gnome.  He's clever, and maybe a little devious....\n\nIf only he liked the taste of humanoid flesh... he'd make a great troll!\n\nHere, <name>.  A deal's a deal, and these tickets are yours." }
WordHunterWoW_QuestEN[7899] = { title = "Small Furry Paws", description = "", objectives = "The first lesson in drawing a crowd is: lure them with gadgets and trinkets!  Can you help me?\n\nI need small furry paws to use for prizes.  You can find those on the cats of the Barrens or Darkshore....\n\nBring me some paws and I'll trade you a Darkmoon Faire ticket for them.", progress = "The first lesson in drawing a crowd is: lure them with gadgets and trinkets!  Can you help me?\n\nI need small furry paws to use for prizes.  You can find those on the cats of the Barrens or Darkshore....\n\nBring me some paws and I'll trade you a Darkmoon Faire ticket for them.", completion = "Great, you got them!  We can use these to make toys and baubles, and those will attract more people to the Faire!\n\nHere's your ticket, <name>.  You earned it!" }
WordHunterWoW_QuestEN[7900] = { title = "Torn Bear Pelts", description = "", objectives = "Children love toys!  And no matter what race, I've found that all children love furry, plushy toys made from torn bear pelts!\n\nYou can get those pelts from the bears of Ashenvale or Hillsbrad.  Bring me a heap of them and earn yourself a heap of Darkmoon Faire tickets!", progress = "Children love toys!  And no matter what race, I've found that all children love furry, plushy toys made from torn bear pelts!\n\nYou can get those pelts from the bears of Ashenvale or Hillsbrad.  Bring me a heap of them and earn yourself a heap of Darkmoon Faire tickets!", completion = "Nice pelts, <name>!  I'll get someone to sew these into a bunch of plush toys.  With a little stuffing and some paint, I think they'll be the envy of children across Azeroth!\n\nTickets?  Ah yes, your payment!  Here they are!" }
WordHunterWoW_QuestEN[7901] = { title = "Soft Bushy Tails", description = "", objectives = "It's amazing what people value!  Take, for instance, a wooden stick with a soft bushy tail attached to it.  Now, you and I might think something like that isn't all that valuable... but if you give that piece of junk a neat name like \"Savage Fuzz Tail\" and put it in a pretty box, then people will think it's valuable.  Trash becomes treasure!\n\nGet me soft bushy tails from the wolves of Desolace and the Badlands, and I'll give you Darkmoon Faire tickets.", progress = "It's amazing what people value!  Take, for instance, a wooden stick with a soft bushy tail attached to it.  Now, you and I might think something like that isn't all that valuable... but if you give that piece of junk a neat name like \"Savage Fuzz Tail\" and put it in a pretty box, then people will think it's valuable.  Trash becomes treasure!\n\nGet me soft bushy tails from the wolves of Desolace and the Badlands, and I'll give you Darkmoon Faire tickets.", completion = "Well done, <name>!  These tails will make great prizes for our visitors, and that means happy visitors... who talk to their friends and bring more visitors!\n\nHere are your tickets!  Have a good time at the Darkmoon Faire... and don't forget to tell your friends about us!" }
WordHunterWoW_QuestEN[7902] = { title = "Vibrant Plumes", description = "", objectives = "A person's imagination is an incredible thing.  It can make the smallest hill seem like the largest mountain.  It can make the most innocuous shadow appear cast by a horrible nightmare!\n\nWe at the Darkmoon Faire let our visitor's imaginations blossom!  But to help stretch their imaginations... sometimes we have to get tricky.\n\nI need vibrant plumes for one of my attractions.  You can get them from the birds of the more dangerous areas of Azeroth.  Bring me the plumes and many tickets will be yours!", progress = "A person's imagination is an incredible thing.  It can make the smallest hill seem like the largest mountain.  It can make the most innocuous shadow appear cast by a horrible nightmare!\n\nWe at the Darkmoon Faire let our visitor's imaginations blossom!  But to help stretch their imaginations... sometimes we have to get tricky.\n\nI need vibrant plumes for one of my attractions.  You can get them from the birds of the more dangerous areas of Azeroth.  Bring me the plumes and many tickets will be yours!", completion = "Ah, the plumes!  They are amazing, don't you think!  It would be easy to spark one's imaginations with such beauties!\n\nYou do such charitable work, <name>.  The smiles on our visitors' faces when they see the show is a grand payment indeed, but please take these tickets as well." }
WordHunterWoW_QuestEN[7903] = { title = "Evil Bat Eyes", description = "", objectives = "Do you ever find yourself wandering in a cave, late at night, looking for adventure?  You do?  Really?  Well, then you've seen the creepy eyes of bats staring at you from high up, waiting for you to let down your guard so they can suck your blood!\n\nScary thought, don't you think?  Of course!  It's no doubt that bat eyes are scary!\n\nWill you bring me some evil bat eyes, <name>?  I want them for... something I'm designing.  Something scary.\n\nYou can get them from the bats of the Eastern Plaguelands.", progress = "Do you ever find yourself wandering in a cave, late at night, looking for adventure?  You do?  Really?  Well, then you've seen the creepy eyes of bats staring at you from high up, waiting for you to let down your guard so they can suck your blood!\n\nScary thought, don't you think?  Of course!  It's no doubt that bat eyes are scary!\n\nWill you bring me some evil bat eyes, <name>?  I want them for... something I'm designing.  Something scary.\n\nYou can get them from the bats of the Eastern Plaguelands.", completion = "Great!  You got the eyes!  I hope hunting those bats was frightening for you, because if it scared a brave <class> like yourself, then those eyes will certainly scare our Faire visitors.\n\nTake these tickets, <name>, and thank you for your service." }
WordHunterWoW_QuestEN[7905] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.", objectives = "Deliver the Free Ticket Voucher to Gelvas Grimegate, located inside the Darkmoon Faire.", progress = "Yes friend, may I help you?  Do you have a voucher that needs redeeming?", completion = "Welcome to the Darkmoon Faire!  This voucher is good for FIVE, yes, FIVE prize tickets and a free copy of the world-renowned Darkmoon Adventurer's Guide!\n\nWhen you accumulate prize tickets, you'll want to speak to me about redeeming them for valuable prizes. This handy field guide will help you to locate and identify items of value to our collectors here at the faire!" }
WordHunterWoW_QuestEN[7906] = { title = "Darkmoon Cards - Beasts", description = "", objectives = "" }
WordHunterWoW_QuestEN[7907] = { title = "Darkmoon Beast Deck", description = "Now that you have gathered all of the Beast cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Beast Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Beasts!   Congratulations!", completion = "So you have put together a deck of Beasts.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[7908] = { title = "Arena Master", description = "There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!Upon completion of this quest you will gain:", objectives = "Speak with Short John Mithril in the Stranglethorn Arena.\n\nProvided item:" }
