WordHunterWoW_QuestEN[7926] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Thunder Bluff in Mulgore!", objectives = "Deliver the Free Ticket Voucher to Gelvas Grimegate, located inside the Darkmoon Faire.", progress = "Yes friend, may I help you?  Do you have a voucher that needs redeeming?", completion = "Welcome to the Darkmoon Faire!  This voucher is good for FIVE, yes, FIVE prize tickets and a free copy of the world-renowned Darkmoon Adventurer's Guide!\n\nWhen you accumulate prize tickets, you'll want to speak to me about redeeming them for valuable prizes. This handy field guide will help you to locate and identify items of value to our collectors here at the faire!" }
WordHunterWoW_QuestEN[7927] = { title = "Darkmoon Portals Deck", description = "Now that you have gathered all of the Portal cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Portals Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Portals!   Congratulations!", completion = "So you have put together a deck of Portals.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[7928] = { title = "Darkmoon Warlords Deck", description = "Now that you have gathered all of the Warlord cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Warlords Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Warlords!   Congratulations!", completion = "So you have put together a deck of Warlords.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[7929] = { title = "Darkmoon Elementals Deck", description = "Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Elementals Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Elementals!   Congratulations!", completion = "So you have put together a deck of Elementals.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[7930] = { title = "5 Tickets - Darkmoon Flower", description = "", objectives = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
