WordHunterWoW_QuestEN[7936] = { title = "50 Tickets - Last Year's Mutton", description = "", objectives = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
WordHunterWoW_QuestEN[7937] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you in Eastvale.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.", objectives = "Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.", progress = "This haystack looks like the one from your vision.", completion = "A quick search of the haystack reveals a lockbox from within it!  It would seem that you have found your fortune!" }
WordHunterWoW_QuestEN[7938] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside the Deadmines.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.You will receive:", objectives = "Travel to the Deadmines in Westfall and seek out your fortune." }
WordHunterWoW_QuestEN[7939] = { title = "More Dense Grinding Stones", description = "", objectives = "<name>, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", progress = "<name>, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", completion = "Again, thank you <name>.  Please enjoy these tickets, and tell your friends about the Darkmoon Faire!" }
WordHunterWoW_QuestEN[7940] = { title = "1200 Tickets - Orb of the Darkmoon", description = "", objectives = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
WordHunterWoW_QuestEN[7941] = { title = "More Armor Kits", description = "", objectives = "<name>, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", progress = "<name>, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", completion = "There you are, <name>.  A fair trade.  Enjoy." }
WordHunterWoW_QuestEN[7942] = { title = "More Thorium Widgets", description = "", objectives = "<name>, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", progress = "<name>, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", completion = "Here you are, <name>.  Here are Darkmoon Faire tickets for your enjoyment.  Do not, as they say, spend them all in one place!" }
WordHunterWoW_QuestEN[7943] = { title = "More Bat Eyes", description = "", objectives = "<name>, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", progress = "<name>, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", completion = "Thanks again, <name>.  Here are your tickets!" }
WordHunterWoW_QuestEN[7944] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside Wailing Caverns.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself.  Stepping through it, a strange chest appears out from nowhere.", objectives = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.", progress = "This chest looks like the one from your vision...", completion = "A quick search of the chest reveals a lockbox from within it!  It would seem that you have found your fortune!" }
WordHunterWoW_QuestEN[7945] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you outside Palemane Rock.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Palemane Rock of Mulgore.  Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.", objectives = "Travel to Palemane Rock in Mulgore and seek out your fortune.", progress = "This tree stump looks like the one from your vision.", completion = "A quick search of the tree stump reveals a lockbox from within it!  It would seem that you have found your fortune!" }
WordHunterWoW_QuestEN[7946] = { title = "Spawn of Jubjub", description = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", objectives = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", progress = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", completion = "Thank you, <name>.  Here is your egg!  It won't be ready to hatch for a little while, but when it does you'll have a great pet!" }
WordHunterWoW_QuestEN[7961] = { title = "Waskily Wabbits!", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us <name>, you're our only hope.Upon completion of this quest you will gain:", objectives = "Collect 10 Unlucky Wabbit Feet from the Waskily Wabbits." }
WordHunterWoW_QuestEN[7962] = { title = "Wabbit Pelts", description = "I want LeCrafty rabbit pelts.  Get me some from LeCrafty Rabbits.\n\nThis is important!You will receive:", objectives = "Bring 3 LeCrafty Rabbit Pelts to Jon LeCraft." }
WordHunterWoW_QuestEN[7981] = { title = "1200 Tickets - Amulet of the Darkmoon", description = "", objectives = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
