WordHunterWoW_QuestEN[8193] = { title = "Grand Prize", description = "", objectives = "Today between 2pm and 4pm we have a contest to determine who the greatest angler of them all is!   Just be the FIRST PERSON to bring me 40 Tastyfish fished from the Tastyfish schools found along the coast of Stranglethorn before anyone else does and you will be declared the Master Angler! \n\n If you are not the first person to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish you bring her.\n\n Oh, and don't delay, Tastyfish go bad quickly!", progress = "Today between 2pm and 4pm we have a contest to determine who the greatest angler of them all is!   Just be the FIRST PERSON to bring me 40 Tastyfish fished from the Tastyfish schools found along the coast of Stranglethorn before anyone else does and you will be declared the Master Angler! \n\n If you are not the first person to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish you bring her.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to be declared the Master Angler!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
WordHunterWoW_QuestEN[8194] = { title = "Apprentice Angler", description = "", objectives = "Even though we already have a contest winner, I will still buy your Tastyfish from you at a reasonable price.   Whadda ya say!", progress = "Even though we already have a contest winner, I will still buy your Tastyfish from you at a reasonable price.   Whadda ya say!", completion = "This deal works for me if it works for you!" }
WordHunterWoW_QuestEN[8195] = { title = "Zulian, Razzashi, and Hakkari Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, <name>, as well as the thanks of the tribe!" }
WordHunterWoW_QuestEN[8196] = { title = "Essence Mangoes", description = "", objectives = "The extremely potent essence mango grows across many of the islands in the South Seas.  A single mango will refresh those who eat it, both physically and mentally.  If you've never had one, you do yourself a disservice!\n\nWe have enough of a supply here on the isle to offer you a handful in exchange for a Zandalar Honor Token.  Speak with Vinchaxa if you need to learn how to get tokens; otherwise, let's get to the business at hand!", progress = "The extremely potent essence mango grows across many of the islands in the South Seas.  A single mango will refresh those who eat it, both physically and mentally.  If you've never had one, you do yourself a disservice!\n\nWe have enough of a supply here on the isle to offer you a handful in exchange for a Zandalar Honor Token.  Speak with Vinchaxa if you need to learn how to get tokens; otherwise, let's get to the business at hand!", completion = "A fair trade, my friend - please enjoy the luscious fruits of the South Seas, with the tribe's blessing." }
WordHunterWoW_QuestEN[8201] = { title = "A Collection of Heads", description = "It is true.  Hakkar now dwells in Zul'Gurub, bathing in the power of our gods.  Enthralled high priests now channel the energies of our most sacred divinities into the Soulflayer, who will soon have a strength beyond any being of Azeroth.  He must be stopped!\n\nTake this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy.\n\nWhen you have done this, return to me.", objectives = "String 5 Channeler's Heads, then return the Collection of Troll Heads to Exzhal on Yojamba Isle.", progress = "Do you have the collection of heads, <name>?  We must stop Hakkar from gaining more power!", completion = "You gained the heads!  You have halted the plundering of our gods' power, and weakened Hakkar!\n\nYour actions are truly heroic, <name>.  May the heads of these troll thralls plead to you for mercy long after their blood chills." }
WordHunterWoW_QuestEN[8221] = { title = "Rare Fish - Keefer's Angelfish", description = "", objectives = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Keefer's Angelfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Keefer's Angelfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Keefer's Angelfish complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
WordHunterWoW_QuestEN[8222] = { title = "Glowing Scorpid Blood", description = "", objectives = "In all my time working the Faire, I've learned a lot of things about customers.  Here's one of those nuggets of wisdom: customers love stuff that glows!  It doesn't matter what it is - you could take a broken chair leg and make it glow, and every child will come from miles around to get one!\n\nSo, <name>, I need glowing scorpid blood.  You can find it from the scorpids of Sillithus, or the Blasted Lands, or the Burning Steppes.", progress = "In all my time working the Faire, I've learned a lot of things about customers.  Here's one of those nuggets of wisdom: customers love stuff that glows!  It doesn't matter what it is - you could take a broken chair leg and make it glow, and every child will come from miles around to get one!\n\nSo, <name>, I need glowing scorpid blood.  You can find it from the scorpids of Sillithus, or the Blasted Lands, or the Burning Steppes.", completion = "Great job, <name>!  Thanks a lot!  I'm going to make paint from this blood and turn all kinds of cheap junk into glowing treasure!\n\nHere are your tickets, and thanks again!" }
WordHunterWoW_QuestEN[8223] = { title = "More Glowing Scorpid Blood", description = "", objectives = "That scorpid blood is working out great, <name>!  It's amazing how a little sparkle and shine can create a prized bauble out of an otherwise piece of junk.  The patrons love the stuff, and love is what it's all about, don't you think...\n\nYou've been a big help to me, <name>, and although I don't have a great need for more glowing scorpid blood, if you bring me more then I'll still trade you some tickets.", progress = "That scorpid blood is working out great, <name>!  It's amazing how a little sparkle and shine can create a prized bauble out of an otherwise piece of junk.  The patrons love the stuff, and love is what it's all about, don't you think...\n\nYou've been a big help to me, <name>, and although I don't have a great need for more glowing scorpid blood, if you bring me more then I'll still trade you some tickets.", completion = "Thanks again, <name>.  Here are your tickets!" }
WordHunterWoW_QuestEN[8224] = { title = "Rare Fish - Dezian Queenfish", description = "", objectives = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Dezian Queenfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Dezian Queenfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Dezian Queenfish complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
WordHunterWoW_QuestEN[8225] = { title = "Rare Fish - Brownell's Blue Striped Racer", description = "", objectives = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Brownell's Blue Striped Racer, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Brownell's Blue Striped Racer, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Brownell's Racer complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
WordHunterWoW_QuestEN[8226] = { title = "Rare Fish - Pale Ghoulfish", description = "", objectives = "" }
WordHunterWoW_QuestEN[8227] = { title = "Nat's Measuring Tape", description = "Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads:\n\n\"Nat Pagle, Dustwallow Marsh.\"", objectives = "Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh.", progress = "Hello there, sonny.  You here to do some fishing?", completion = "Why, you found my favorite measuring tape!  I love this tape!  I measured some of the biggest fish I ever caught with it...\n\nBut, I lost this tape in Zul'Gurub... you've been to Zul'Gurub?  Did you see the fabled Gahz'ranka?\n\nWell... do you want to catch him?" }
WordHunterWoW_QuestEN[8228] = { title = "Could I get a Fishing Flier?", description = "", objectives = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", progress = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", completion = "There is a Fishing Contest in Booty Bay this Sunday!   Here are the rules of the tournament if you want to participate!" }
WordHunterWoW_QuestEN[8229] = { title = "Could I get a Fishing Flier?", description = "", objectives = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", progress = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", completion = "There be a Fishin Contest in Booty Bay this Sunday!   Here are the rules for ya!" }
WordHunterWoW_QuestEN[8230] = { title = "Collin's Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[8231] = { title = "Wavethrashing", description = "The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient.\n\nThe tough, reflective scales from a wavethrasher mirror the strength of the hunter.\n\nTrack and hunt wavethrashers along the coast of Azshara, and bring me their scales.Upon completion of this quest you will gain:", objectives = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." }
WordHunterWoW_QuestEN[8232] = { title = "The Green Drake", description = "Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.\n\nIf you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him.\n\nThe drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.You will be able to choose one of these rewards:", objectives = "Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." }
WordHunterWoW_QuestEN[8233] = { title = "A Simple Request", description = "Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.\n\nRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep.Upon completion of this quest you will gain:", objectives = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor." }
WordHunterWoW_QuestEN[8234] = { title = "Sealed Azure Bag", description = "First things first.  What I've lost is a small blue bag, the contents of which are a private matter.\n\nDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.\n\nI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara." }
WordHunterWoW_QuestEN[8235] = { title = "Encoded Fragments", description = "Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.\n\nUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.\n\nIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill the beasts of Azshara, since they have a tendency to pick up just about anything.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara." }
WordHunterWoW_QuestEN[8236] = { title = "The Azure Key", description = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.\n\nThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.\n\nGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return the Azure Key to Lord Jorach Ravenholdt." }
WordHunterWoW_QuestEN[8237] = { title = "In the Blink of an Eye Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[8238] = { title = "Gurubashi, Vilebranch, and Witherbark Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, <name>, as well as the thanks of the tribe!" }
WordHunterWoW_QuestEN[8239] = { title = "Sandfury, Skullsplitter, and Bloodscalp Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, <name>, as well as the thanks of the tribe!" }
WordHunterWoW_QuestEN[8240] = { title = "A Bijou for Zanza", description = "The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves!\n\nTake any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it.  For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive.\n\nWitness for yourself the blessings of Zanza!", objectives = "Destroy any one of the Hakkari Bijous found in Zul'Gurub at the Altar of Zanza on Yojamba Isle. When done, speak with Vinchaxa nearby.The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves!\n\nTake any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it. For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive.\n\nWitness for yourself the blessings of Zanza!", completion = "Excellent... each bijou we wrest away from the Blood God's minions is one step closer we all are to finally defeating them once and for all.  You bring honor to the Zandalar - and yourself - through your noble actions.\n\nRemember <name>, you may always destroy the bijous you find in Zul'Gurub at the altar.  For each one, you will gain recognition and an Honor Token!  Just remember to have an open space in your inventory if you don't have one of the tokens already." }
WordHunterWoW_QuestEN[8241] = { title = "Restoring Fiery Flux Supplies via Iron", description = "", objectives = "Let's not waste more of my precious time with jibber jabber, <race>. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Iron bars.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", progress = "Let's not waste more of my precious time with jibber jabber, <race>. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Iron bars.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", completion = "There's always room for more fiery flux, junior. Keep it comin'... unless I tell you to stop." }
WordHunterWoW_QuestEN[8242] = { title = "Restoring Fiery Flux Supplies via Heavy Leather", description = "", objectives = "Let's not waste more of my precious time with jibber jabber, <race>. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Heavy Leather.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", progress = "Let's not waste more of my precious time with jibber jabber, <race>. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Heavy Leather.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", completion = "There's always room for more fiery flux, junior. Keep it comin'... unless I tell you to stop." }
WordHunterWoW_QuestEN[8243] = { title = "Zanza's Potent Potables", description = "", objectives = "With your increased status amongst the tribe comes access to some of our more potent potables.  Behold... these brews are strong in the mojo - blessed by Zanza and fit for adventurers from all walks of life!\n\nI will allow you to choose one from the three I offer; in exchange, I require one Zandalar Honor Token.  Note that only the effects of a single one may course through your spirit at any given time.\n\nLet me know when you're ready to barter!", progress = "With your increased status amongst the tribe comes access to some of our more potent potables.  Behold... these brews are strong in the mojo - blessed by Zanza and fit for adventurers from all walks of life!\n\nI will allow you to choose one from the three I offer; in exchange, I require one Zandalar Honor Token.  Note that only the effects of a single one may course through your spirit at any given time.\n\nLet me know when you're ready to barter!", completion = "A fair trade, my friend - please enjoy the blessings of Zanza with our compliments!" }
WordHunterWoW_QuestEN[8246] = { title = "Signets of the Zandalar", description = "", objectives = "<name> - for someone as exalted among the Zandalar as you are, I have something very special for you.  Direct from our home in the South Seas... the Signets of the Zandalar!  These signets are used to enhance any shoulder item you may possess.  Should you seek might, mojo, or serenity - I have what you need!\n\nI ask for fifteen Zandalar Honor Tokens in exchange for your choice of one signet.  If you have the tokens ready, then I'm ready to make a deal!", progress = "<name> - for someone as exalted among the Zandalar as you are, I have something very special for you.  Direct from our home in the South Seas... the Signets of the Zandalar!  These signets are used to enhance any shoulder item you may possess.  Should you seek might, mojo, or serenity - I have what you need!\n\nI ask for fifteen Zandalar Honor Tokens in exchange for your choice of one signet.  If you have the tokens ready, then I'm ready to make a deal!", completion = "A fair trade, my friend - please accept your signet with the blessing of the tribe!" }
WordHunterWoW_QuestEN[8249] = { title = "Junkboxes Needed", description = "", objectives = "My rogues need to hone their lockpicking skills, and I need locks of adequate difficulty -- the stuff Zan makes us is unfit for all but the lowliest neophytes.\n\nTell ya what, if you bring me 5 Heavy Junkboxes, I'll provide you with some of the finest throwing knives known to roguekind.\n\nYou can unlock the boxes and rifle through them, but you'll have to leave at least a few coins in them... even a rogue in training needs motivation.", progress = "My rogues need to hone their lockpicking skills, and I need locks of adequate difficulty -- the stuff Zan makes us is unfit for all but the lowliest neophytes.\n\nTell ya what, if you bring me 5 Heavy Junkboxes, I'll provide you with some of the finest throwing knives known to roguekind.\n\nYou can unlock the boxes and rifle through them, but you'll have to leave at least a few coins in them... even a rogue in training needs motivation.", completion = "May these knives find a place in someone's heart.\n\nLiterally." }
WordHunterWoW_QuestEN[8250] = { title = "Magecraft", description = "Archmage Xylem has been asking around lately... for someone of your experience.\n\nIf you wish to seek him out, you can find him in Azshara.  His tower is built high atop the cliffs, and the only way up is a teleport spell invoked by his arrogant servant, Sanath Lim-yo.\n\nSanath makes camp below his master's tower.  To find him, travel to where Azshara's main road forks at the entrance to the Ruins of Eldarath.  From that spot, head directly north until you reach the cliffs.Upon completion of this quest you will gain:", objectives = "Seek out Sanath Lim-yo and gain passage to see Archmage Xylem." }
WordHunterWoW_QuestEN[8251] = { title = "Magic Dust", description = "The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.\n\nWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.\n\nThe time for talk is over, <name>.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust.Upon completion of this quest you will gain:", objectives = "Bring 10 Glittering Dust to Archmage Xylem." }
WordHunterWoW_QuestEN[8252] = { title = "The Siren's Coral", description = "Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.\n\nSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Enchanted Coral and return them to Archmage Xylem." }
WordHunterWoW_QuestEN[8253] = { title = "Destroy Morphaz", description = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.\n\nYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.\n\nYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.You will be able to choose one of these rewards:", objectives = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem." }
WordHunterWoW_QuestEN[8254] = { title = "Cenarion Aid", description = "It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.\n\nThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.Upon completion of this quest you will gain:", objectives = "Seek out Ogtinc in Azshara.It is the way of the divine to help those in need. The how is insignificant -- only the why matters.\n\nThe Cenarion Circle has such a need. Speak with Ogtinc to lend aid to their plight. He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[8255] = { title = "Of Coursers We Know", description = "The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.\n\nIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood.Upon completion of this quest you will gain:", objectives = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." }
WordHunterWoW_QuestEN[8256] = { title = "The Ichor of Undeath", description = "For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.\n\nPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.\n\nDue to the potency of this vile element, I require only a single ichor.Upon completion of this quest you will gain:", objectives = "Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." }
WordHunterWoW_QuestEN[8257] = { title = "Blood of Morphaz", description = "Now the last part, the second cure.\n\nThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.\n\nA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.You will be able to choose one of these rewards:", objectives = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows." }
WordHunterWoW_QuestEN[8258] = { title = "The Darkreaver Menace", description = "Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  <name>, bring me his head!  Only his demise will reverse the damage done to the spirit realm!You will receive:", objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.\n\nBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar." }
WordHunterWoW_QuestEN[8259] = { title = "A More Fitting Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[8260] = { title = "Arathor Basic Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored." }
WordHunterWoW_QuestEN[8261] = { title = "Arathor Standard Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored." }
WordHunterWoW_QuestEN[8262] = { title = "Arathor Advanced Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored." }
WordHunterWoW_QuestEN[8263] = { title = "Defiler's Basic Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Honored with us, and bandages when you are Revered." }
WordHunterWoW_QuestEN[8264] = { title = "Defiler's Standard Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Honored with us, and bandages when you are Revered." }
WordHunterWoW_QuestEN[8265] = { title = "Defiler's Advanced Care Package", description = "", objectives = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items can make the difference between life and death. We need you in top fighting shape if we're to achieve victory!" }
WordHunterWoW_QuestEN[8266] = { title = "Ribbons of Sacrifice", description = "", objectives = "" }
WordHunterWoW_QuestEN[8267] = { title = "Ribbons of Sacrifice", description = "", objectives = "" }
WordHunterWoW_QuestEN[8268] = { title = "Ribbons of Sacrifice", description = "", objectives = "" }
WordHunterWoW_QuestEN[8269] = { title = "Ribbons of Sacrifice", description = "", objectives = "" }
WordHunterWoW_QuestEN[8270] = { title = "test copy quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[8271] = { title = "Hero of the Stormpike", description = "", objectives = "As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures." }
WordHunterWoW_QuestEN[8272] = { title = "Hero of the Frostwolf", description = "", objectives = "How does it feel, <name>? How does it feel to crush your enemies and watch their lines break apart? It feels good, doesn't it?\n\nYou should be rewarded for this heroic deed, soldier." }
WordHunterWoW_QuestEN[8273] = { title = "Oran's Gratitude", description = "", objectives = "Now isn't this interesting? You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, <class>? Very interesting indeed. \n\nI thank you for your efforts in this matter. Our Dark Lady shall be very pleased with this discovery. Here, allow me to reward you proportionately." }
WordHunterWoW_QuestEN[8274] = { title = "Test Kill Quest", description = "Got some time to spare?  Kill me some Murlocs and I'll give you something shiny!", objectives = "Kill 5 Murlocs and come back to the test character." }
WordHunterWoW_QuestEN[8275] = { title = "Taking Back Silithus", description = "Attention, heroes of the Alliance!  The silithid menace has been left unchecked for too long.  Unfettered by any real opposition, they've been preparing all this time for a large-scale expansion.  \n\nCenarion Circle forces are gathering in Silithus to take the fight to these wretched creatures and all able-bodied adventurers are hereby called to join us!\n\nDon't wait until it's too late!  Aid us in the defense of Azeroth! Report to Windcaller Proudhorn at Cenarion Hold for specific instructions!", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, <class>.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause." }
WordHunterWoW_QuestEN[8276] = { title = "Taking Back Silithus", description = "Attention, champions of the Horde!  There's a threat we've left unchallenged for too long.  Tremors in the earth near silithid hives all around Azeroth have alerted us to large movements in their numbers as they prepare for expansion.\n\nCenarion Circle forces are gathering in Silithus to take the fight to the silithid before it's too late!  No more shall they defile our lands!\n\nAll able-bodied combatants are to report to Windcaller Proudhorn at Cenarion Hold!  The silithid shall be vanquished!", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, <class>.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause." }
WordHunterWoW_QuestEN[8277] = { title = "Deadly Desert Venom", description = "Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins.\n\nI've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him.\n\nNoggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote for him.", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.", progress = "Are you done collecting those samples?  We could lose Noggle any minute now!", completion = "Cross your fingers, friend!  Here's to hoping we can save Noggle!" }
WordHunterWoW_QuestEN[8278] = { title = "Noggle's Last Hope", description = "Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south.\n\nI'm going to need you to go there and get me some more samples, {name}.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.", progress = "This is our last chance to save Noggle!  Hurry!", completion = "Yes!  It seems to be working, Noggle is coming to.  We owe ya big time!" }
WordHunterWoW_QuestEN[8279] = { title = "The Twilight Lexicon", description = "The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine!\n\nTo decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers.  Look for them at the Twilight's Hammer camps.", objectives = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.", progress = "Who goes there?  Oh, it's you!  Did you find all the Lexicon chapters yet?", completion = "Yes! These are the parts to the book!  Let's get started then, <name>.\n\nSwap every third word with words from the second chapter... then swap every other word with words from the first chapter...  Wait, did I get that backwards?" }
WordHunterWoW_QuestEN[8280] = { title = "Securing the Supply Lines", description = "Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is.\n\nDesert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.", completion = "You have my sincere gratitude.  Your efforts in helping Cenarion Hold have shown true courage." }
WordHunterWoW_QuestEN[8281] = { title = "Stepping Up Security", description = "Your performance has been truly exemplary so far, {name}.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.\n\nYou'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.  ", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.", completion = "Excellent!  You've proven to be a valuable ally in preparing for the war against the silithid." }
WordHunterWoW_QuestEN[8282] = { title = "Noggle's Lost Satchel", description = "Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers.\n\nThe satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents.\n\nI ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.", objectives = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.", progress = "Still haven't found my bag?  Well I should count my lucky stars, at least the poison's been cleansed.", completion = "Yes!  You brought my satchel back.  And my rare reagents are all here!  I'll be in your debt for a long time." }
WordHunterWoW_QuestEN[8283] = { title = "Wanted - Deathclasp, Terror of the Sands", description = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.", objectives = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.", progress = "I'll need the creature's pincer as proof of the deed.  No pincer, no reward.", completion = "Excellent!  With Deathclasp gone we're free to use the southern mountain range as a strategic path to circumvent the silithid hives.  Your work is greatly appreciated." }
WordHunterWoW_QuestEN[8284] = { title = "The Twilight Mystery", description = "A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was.\n\nI've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.", progress = "The ravaged camp can be found northwest of here.  Come back when you have all the fragments.", completion = "Just as I suspected.  I can decipher individual words in the tablets but they appear to be devoid of any logic or meaning.  It's not unknown for Twilight's Hammer sects to use a code to hide the meaning of their texts; we'll have to go to someone who knows more about this sort of thing." }
WordHunterWoW_QuestEN[8285] = { title = "The Deserter", description = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet.\n\nTake the restored tablet with you and seek out Ortell.", objectives = "Take the restored tablet to Hermit Ortell in Silithus.", progress = "You!  How did you find me?  Who are you?  You weren't followed, were you?  Speak!", completion = "I see you're familiar with my old organization.  You must be with Cenarion Hold.  \n\nYou seek information to use against them?  Come closer, perhaps we can be of mutual assistance." }
WordHunterWoW_QuestEN[8286] = { title = "What Tomorrow Brings", description = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.\n\n\"Forever you will remain if you must,\" he said, and with those words I was bound as a Watcher.\n\nLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed.", objectives = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.", completion = "It is as it should be - the great one has risen. My watch comes to an end..." }
WordHunterWoW_QuestEN[8287] = { title = "A Terrible Purpose", description = "Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.  \n\nTake this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!", objectives = "Take the Decoded Tablet Parchment to Commander Mar'alith.", progress = "What is this you bring to me, <name>?", completion = "This is very interesting information indeed, <name>.  This sheds some light on the presence of the Twilight's Hammer in Silithus and will undoubtedly help us in our struggle against them.  Your efforts will be handsomely rewarded, <class>." }
WordHunterWoW_QuestEN[8288] = { title = "Only One May Rise", description = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.\n\nWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey.", objectives = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.", progress = "It is the favor of the Brood of Nozdormu that you must earn.", completion = "Could you be the first to earn favor among the Bronze Flight in a thousand years?" }
WordHunterWoW_QuestEN[8289] = { title = "Talismans of Merit", description = "", objectives = "" }
WordHunterWoW_QuestEN[8290] = { title = "Vanquish the Invaders", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[8291] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[8292] = { title = "Talismans of Merit", description = "", objectives = "" }
WordHunterWoW_QuestEN[8293] = { title = "Mark of Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[8294] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, <race>. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, <name>, and you will be rewarded.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp." }
WordHunterWoW_QuestEN[8295] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, <race>. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, <name>, and you will be rewarded.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp." }
WordHunterWoW_QuestEN[8296] = { title = "Mark of Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[8297] = { title = "Arathi Basin Resources!", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe." }
WordHunterWoW_QuestEN[8298] = { title = "More Resource Crates", description = "", objectives = "" }
WordHunterWoW_QuestEN[8299] = { title = "Cut Arathor Supply Lines", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall." }
WordHunterWoW_QuestEN[8300] = { title = "More Resource Crates", description = "", objectives = "" }
WordHunterWoW_QuestEN[8301] = { title = "The Path of the Righteous", description = "The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master.\n\nHive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve.", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", progress = "There is much history rooted in their distrust of the mortal races; but alas, such is a tale better left for the Brood to tell when the time is right.", completion = "You are not alone, hero. I will now grant you the ability to deputize others to help you in your quest.  If you are to be the champion of your people, you will need assistance in your tasks and duties." }
WordHunterWoW_QuestEN[8302] = { title = "The Hand of the Righteous", description = "Choose your deputies wisely, mortal. Each time you return with your task complete, a new deputy you will be allowed to choose.\n\nWith that said, I require more of the carapace fragments. Waste no time!", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", progress = "Perhaps one day the whole of Cenarion Hold will be working under your command.", completion = "Well done, hero. You will now be granted the ability to deputize another Agent of Nozdormu." }
WordHunterWoW_QuestEN[8303] = { title = "Anachronos", description = "It is time, <name>.\n\nI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.", objectives = "Seek out Anachronos at the Caverns of Time in Tanaris.\n\nProvided item:", completion = "You are the hope of Kalimdor, <name>." }
WordHunterWoW_QuestEN[8304] = { title = "Dearest Natalia", description = "My dear Natalia has gone missing.\n\nTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.\n\nShe was last seen heading to Bronzebeard's camp to the south.\n\nMy soldiers are spread too thin, {name}. I need you to go to Bronzebeard's camp and question those dwarves. ", objectives = "Question Frankal and Rutgar at Bronzebeard's Encampment about the whereabouts of Natalia Mar'alith.", completion = "<Commander Mar'alith lowers his head in contemplation.>\n\nWhether she is alive or dead, I must do what is right. She must be found. Alas, I am bound by duty to this outpost. Will you help me once more, <name>?" }
WordHunterWoW_QuestEN[8305] = { title = "Long Forgotten Memories", description = "In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment.", objectives = "Locate the Crystalline Tear in Silithus and gaze into its depths.", completion = "You can feel a great sorrow revolving around this crystal. The force is so powerful that you feel as if you might collapse and die of sadness." }
WordHunterWoW_QuestEN[8306] = { title = "Into The Maw of Madness", description = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, {name}. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive.\n\nAnd {name}, if she truly is as mad as they say... do what you must.", objectives = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.\n\nDo not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.\n\nAnd <name>, remember the Commander's words: \"Do what you must...\"", progress = "Natalia?", completion = "<Commander Mar'alith clutches at his chest.>\n\nC'Thun? WHAT is the meaning of all this? What is C'Thun? How could this fiend have turned my sweet Natalia into the monster that you described?" }
WordHunterWoW_QuestEN[8307] = { title = "Desert Recipe", description = "Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many.\n\nI've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anything.", objectives = "Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.", completion = "This book contains several common recipes and a few unusual ones.  After browsing through it for a few seconds you spot a recipe that involves sandworm meat." }
WordHunterWoW_QuestEN[8308] = { title = "Brann Bronzebeard's Lost Letter", description = "To Whom It May Concern:\n\nIf you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow.\n\nFound information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it.\n\nTake this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs.\n\n-Brann Bronzebeard, Explorer Extreme\n\nP.S. Watch out for crazy Old God worshipping night elf.", objectives = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.", progress = "Oh dear.", completion = "Well this explains a lot. If you ever find a way into Ahn'Qiraj, keep an eye out for ol' Brann. I'm afraid that he'll be powerless without his monkey." }
WordHunterWoW_QuestEN[8309] = { title = "Glyph Chasing", description = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.\n\nIf I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness.\n\nTake this transcription set  and hit Hive'Regal to the east, {name}. That's the last rubbing I need!", objectives = "Use the Geologist's Transcription Kit to make a Hive'Regal Rubbing from the Hive'Regal Glyphed Crystal.", progress = "If you find some crazy night elf lass in there, be sure to give her a kick in the duff.", completion = "I can't make heads or tails of these glyphs. I've never seen anything like it! I hope Frankal's research can shed some light on this mess." }
WordHunterWoW_QuestEN[8310] = { title = "Breaking the Code", description = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! \n\nWhat do I need? Glad you asked! I need brains!\n\nNormally I'd need a brain from each silithid type that inhabit the hives. Another brave explorer brought me two of 'em here... and never came back from Hive'Regal.\n\nBring me back a silithid brain from Hive'Regal... and be careful not to end up like him!", objectives = "Obtain an intact Hive'Regal Silithid Brain from any silithid in Hive'Regal.", progress = "Go play with the monkey, kid. I don't have time for this.", completion = "Outstanding! Don't wander off too far, kid. We might need you to take on another task or two." }
WordHunterWoW_QuestEN[8311] = { title = "Hallow's End Treats for Jesper!", description = "I'm not allowed to go trick-or-treating.  After Deathwing's attack, I'm lucky Matron Nightingale lets me be this far away.\n\nIf you trick-or-treat for me, I'd trade you the candy you get for some I already have!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge. Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Jesper in front of Stormwind with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.", progress = "Have you finished trick-or-treating yet? I wish I could go, but I don't want to run into Deathwing.", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, <name>!" }
WordHunterWoW_QuestEN[8312] = { title = "Hallow's End Treats for Spoops!", description = "I want to keep trick-or-treating, but I can't because the Matron won't let me.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Orgrimmar is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik Orgrimmar's Valley of Spirits. Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Spoops in the Ruins of Lordaeron with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.", progress = "Have you finished trick-or-treating yet?  The Matron said we could pick one place to visit, at least there is a lot happening here.", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, <name>!" }
WordHunterWoW_QuestEN[8313] = { title = "Sharing the Knowledge", description = "While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.  ", objectives = "Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.", progress = "Did you learn the recipe?  You won't keep it to yourself, I hope!", completion = "Let's have a look at that...\n\nThis seems simple enough.  They have their own names for some of the herbs, but those are simple enough to figure out.  Here, let me show you!" }
WordHunterWoW_QuestEN[8314] = { title = "Unraveling the Mystery", description = "We're on the verge of a breakthrough, {name}! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.\n\nUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.\n\nTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.", objectives = "Deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.", progress = "Oh my! What do you have there, <name>?", completion = "The reason the dwarves could not decipher the glyphs is because there is nothing to decipher. The shifting outer layer of the prism must properly align with the inner crystal's markings in order for the message to be transmitted. Clever...\n\nWhile we should be able to translate this data, we must first unlock the code. There is only one clue on the surface of the prism - assuming the rubbings were transferred correctly - and it looks grim." }
WordHunterWoW_QuestEN[8315] = { title = "The Calling", description = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary.\n\nI will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the crystals...", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.\n\nYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.\n\nAssemble an army for this task, <name>!", progress = "You must take the opportunity as it presents itself and strike!", completion = "I hold 20,000 years of history in my hands, <name>!" }
WordHunterWoW_QuestEN[8316] = { title = "Armaments of War", description = "", objectives = "War comes, <name>, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n<Geologist Larksbane turns pale.>\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert." }
WordHunterWoW_QuestEN[8317] = { title = "Kitchen Assistance", description = "That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.", objectives = "Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.", progress = "How are those dumplings coming along?", completion = "Excellent!  You're a life saver.  These dumplings turned out to be quite good.  Didn't really expect such good taste from the Twilight's Hammer." }
WordHunterWoW_QuestEN[8318] = { title = "Secret Communication", description = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, {class}.\n\nI can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!", objectives = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.", progress = "Did you bring me some texts?", completion = "Excellent!  I'll stash these away, maybe they'll be useful later." }
WordHunterWoW_QuestEN[8319] = { title = "Encrypted Twilight Texts", description = "", objectives = "Keep bringing me texts.  We'll soon force the Twilight's Hammer out of Silithus.", progress = "Keep bringing me texts.  We'll soon force the Twilight's Hammer out of Silithus.", completion = "Excellent work!  I'll put a good word in for you." }
WordHunterWoW_QuestEN[8320] = { title = "Twilight Geolords", description = "The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night.  We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert.\n\nAlthough their mystery may one day be solved, we must first deal with their immediate threat.  Go to their camps to the west and seek out Twilight geolords.  They are the heads of these serpents; that is where we must strike!", objectives = "Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.", completion = "That was a task well performed, <name>.  Your slaying of the Twilight geolords must have dealt a grievous blow to the cult.  Let us hope their plans are slowed..." }
WordHunterWoW_QuestEN[8321] = { title = "Vyral the Vile", description = "We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.\n\nFortune to you, {name}.  The horrors of Twilight's Run are formidable indeed.", objectives = "Slay Vyral the Vile and obtain Vyral's Signet Ring.", progress = "<name>, have you yet defeated Vyral the Vile?  Do you have his signet ring?", completion = "You've done it!  Vyral is killed!  This can only mean doom for the Twilight Hammer's operations in Silithus.  There may be more of them scurrying about, but the blow you dealt to the cult today is one from which they will not easily recover." }
WordHunterWoW_QuestEN[8322] = { title = "Rotten Eggs", description = "The humans of Southshore love their ale, and as such they prize the ale served at the Southshore Inn.  With the chaos of Hallow's End now upon them, we can use it to ruin their latest batch of beverages for weeks - if not months to come!\n\nTake these rotten eggs and place them in the main brew keg inside the Southshore Inn.  Your presence alone will cause strife, so be prepared to defend yourself!\n\nOnce you've given Southshore a taste they'll not soon forget, return to me here at the festival!Upon completion of this quest you will gain:", objectives = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn." }
WordHunterWoW_QuestEN[8323] = { title = "True Believers", description = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you.\n\nMy former organization has a secret encoded bulletin they circulate on a monthly basis.\n\nIf they make any progress searching for me or if they call off the search, word will be published on the True Believer.\n\nAlthough this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer members.", objectives = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts.", progress = "Did you find any encrypted texts?  I'm quite curious to read this month's True Believer.", completion = "Excellent!  I will get to decoding these as soon as possible.  If I find anything of interest I'll find some way to get the information to you." }
WordHunterWoW_QuestEN[8324] = { title = "Still Believing", description = "", objectives = "Find any more encrypted texts?  Bring me a good batch of them, this decoding work takes some time.", progress = "Find any more encrypted texts?  Bring me a good batch of them, this decoding work takes some time.", completion = "Excellent!  I can't wait to read these.  Please do keep bringing the encrypted texts here if you find them." }
WordHunterWoW_QuestEN[8325] = { title = "Reclaiming Sunstrider Isle", description = "The sooner you begin your education, {name}, the better for us all.  There is little room for error, so listen closely.\n\nThe Burning Crystals - the green floating objects to the west of the Sunspire here - have long been used to power the isle's experimentations.  The mana wyrms were their guardians, but the Scourge invasion of Quel'Thalas has driven them errant from our lack of magical control over them.\n\nThere is little choice but to thin their numbers for reclamation.  Do this, then return to me.", objectives = "Kill 6 Mana Wyrms; they are located close to the Burning Crystals that are adjacent to the tower and gazebo.", progress = "Our work in rebuilding our society begins here, <name>.  Once we are able to secure our home, we can look outward and upward.", completion = "You have successfully completed your first task; for that, you are to be congratulated.  Such success gives me faith that you will turn out better than those young blood elves who fail to heed the lessons of their masters.  Continued success will be rewarded - not only with knowledge, but also with tangible rewards as well.\n\nYour work here, however, is not finished.  There is much more to learn, my young friend..." }
WordHunterWoW_QuestEN[8326] = { title = "Unfortunate Measures", description = "Your effort has made something clear that, honestly, I wish were not true.  The unchecked power of the Burning Crystals has maligned a much larger swath of the isle's natural balance than I thought.  We must now take on more unfortunate measures to reclaim control.\n\nThe nearby lynxes have succumbed to the influence of the crystals, and they must be put down.  Bring their collars, {name}, as I may yet be able to fashion a magical restraint to turn some back from being uncontrolled.", objectives = "Collect 8 Lynx Collars from slain Springpaw Lynxes and Springpaw Cubs. Return to Magistrix Erona on Sunstrider Isle when you are done.", progress = "It gives me no pleasure to ask you to destroy these beasts.  While in times past we have lived in relative harmony with woodland creatures, these are different times.  The first order of business for all sin'dorei is survival; make sure you remember that.", completion = "The tower and surrounding areas should now be relatively secure, though only for the time being.  You have done well in providing us with a buffer of security, but we will need to reassert control over the entire isle if we are to survive here in the long run.  This will involve tackling much greater threats than errant mana wyrms and lynxes.\n\nTake this, <name> - you will no doubt make good use of it for the tasks to come." }
WordHunterWoW_QuestEN[8327] = { title = "Report to Lanthan Perilon", description = "You are to report to my assistant, Lanthan Perilon.  He will instruct you on what needs to be done next.  While we here at the Sunspire will continue to rein in the Burning Crystals, you will be focused on a more pressing matter concerning Falthrien Academy.  Lanthan will explain fully when you speak to him.\n\nSimply walk west of here along the path, and you should see him standing close by.\n\nGood luck, {name} - your continued successes shall be rewarded.", objectives = "Speak with Lanthan Perilon on Sunstrider Isle; he is standing close to the path running west away from the Sunspire.", completion = "Magistrix Erona told me you'd be along quick enough, <name>.  The Falthrien Academy to our west - the huge floating building with the ornate spires - is in bad shape.  You're going to be leading the effort to recapture it from one of the Wretched - a <race> who has forever succumbed to their basest cravings.\n\nI hope you're ready to work.  This is not only going to be a lesson about danger, but also of what happens when you forsake the realities of who you are." }
WordHunterWoW_QuestEN[8328] = { title = "Mage Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young mages here on Sunstrider Isle, your trainer is Julia Sunstriker.  Speak with Julia and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nJulia - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Julia Sunstriker - the Mage class trainer - inside the Sunspire on Sunstrider Isle.", completion = "Ah, <name> - I believe you're one of the new mages here on the isle, yes?  Well, you've come to the right place.  If arcane mastery is what you seek, then I can provide such knowledge - as long as you have the wherewithal to handle training costs and the capacity to focus on the lessons I'll be teaching.\n\nLet's get started!" }
WordHunterWoW_QuestEN[8329] = { title = "Warrior Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young warriors here on Sunstrider Isle, your trainer is Delios.  Speak with him and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nDelios - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Delios, the warrior class trainer, inside the Sunspire on Sunstrider Isle.", completion = "Welcome to the Sunspire, young <class>!  Mastery of weapons and battle tactics begins here and now - all I ask of my pupils is that they cover payment for training costs that may come up, and that they are as good of a listener as they are an aspiring <class>.  The lessons I have to teach are extensive, and I don't like to repeat myself unnecessarially.\n\nLet's get to it then!" }
WordHunterWoW_QuestEN[8330] = { title = "olanian's Belongings", description = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle.  I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead.\n\nI need my scrying orb, my scroll of Scourge magic, and my journal.  Use this satchel for some extra space, as my things are rather bulky.  Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", objectives = "Collect Well Watcher Solanian's Scrying Orb, his Scroll of Scourge Magic, and his Journal. They are found on Sunstrider Isle by the pond, the fountain, and one of the Burning Crystals. Return them to the Well Watcher at the Sunspire on Sunstrider Isle when you've collected them all.", progress = "Have you had a chance to find my belongings?  Once we reassert our dominance over Sunstrider Isle, I will need them in my work.  For now though, I must maintain my watch over the Sunwell... or what remains of it.", completion = "Well done - I knew you'd be perfect for the task.  Once it's safe to make use of our outdoor facilities on the isle, I'll be putting these things to good use.\n\nLike I mentioned, please feel free to keep the satchel.  Also, you may find this piece of armor to be useful.  Consider it ample compensation for a simple task performed dutifully!" }
WordHunterWoW_QuestEN[8331] = { title = "Aurel Goldleaf", description = "<name>, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken.  Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps.  Your next action, <name>, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold.  Her skill will be needed for this next gambit.", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.<name>, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken. Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps. Your next action, <name>, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold. Her skill will be needed for this next gambit.", completion = "<name>, good day.  I was told you will pit yourself against the Abyssal Council?  If that is so, then listen closely to my next words..." }
WordHunterWoW_QuestEN[8332] = { title = "Dukes of the Council", description = "We think it is possible to use a wind stone to ambush a duke of the Abyssal Council.  To do this, however, one must commune through the wind stone, and convince the council you are a middle ranked leader of the Twilight's Hammer.  \n\nSuch a gambit requires a replica of the cult's medallion of station.  I can create the medallion, but I will need a large brilliant shard, and crests worn by the Abyssal Templar.\n\nBring these to me and I will do the rest.", objectives = "Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.", progress = "Do you have the shard and the crests, <name>?  I will need them to make the twilight cultist's medallion of station.", completion = "Ah, very good.  I've been working on the medallion - now with these last ingredients, I'll be done in just a few moments...\n\nThere we are.  Here is the medallion, <name>.\n\nYou'll need to wear this when you activate one of the Twilight's Hammer's wind stones.  Put this on, along with the rest of the twilight trappings, and the Abyssal Council will see you as one of their cultist underlings." }
WordHunterWoW_QuestEN[8333] = { title = "Medallion of Station", description = "", objectives = "If you need another Twilight cultist's medallion of station, then I am happy to oblige.  I will, however, need another brilliant shard and some abyssal crests...", progress = "If you need another Twilight cultist's medallion of station, then I am happy to oblige.  I will, however, need another brilliant shard and some abyssal crests...", completion = "Here you are, <name>.  One more Twilight medallion of station.  Use it well, and I wish you luck against the Abyssal Council!" }
WordHunterWoW_QuestEN[8334] = { title = "Aggression", description = "Before sending you to the Academy, I want you on another task that needs to be dealt with immediately.  Once used to aid us in the gardening of Sunstrider Isle, the bestial tenders now have grown out of our control.  Clear them out with due haste, but be warned - their lack of control has made them aggressive.  It is such aggression that forces us to put down these once-gentle servants.\n\nIt doesn't please me to ask you to do such a task, but survival is survival.  I'll mourn later.", objectives = "Kill 7 Tenders and 7 Feral Tenders, and then return to Lanthan Perilon on Sunstrider Isle.", progress = "It is better you learn about survival - and the costs of survival - now rather than later.  Making hard choices is something you're going to have to get used to as a <race>.\n\nNo one was there for us when the Scourge ripped our home in two.  It was us and us alone who pulled ourselves up by the bootstraps.", completion = "While the deaths of the tenders give me no joy whatsoever, it does show me that you're ready for the most important task you'll do here on Sunstrider Isle.  Take this and put it to good use; you'll need good items and sharp wits for the task ahead.  Our reassertion of control over the island depends on it." }
WordHunterWoW_QuestEN[8335] = { title = "Felendren the Banished", description = "A betrayer of our people resides atop Falthrien Academy to the southwest.\n\nFelendren is his name, and he was banished from blood elf lands for failing to heed the warnings of our teachers and elders.  He is the worst of our society, as he lives only to feed his insatiable magical addictions.  He refused to learn control; he is a shell of his former self - one of the Wretched - and he is a threat to the Sunspire.\n\nDestroy him and the wraiths he uses as minions.", objectives = "Kill 8 Arcane Wraiths and 2 Tainted Arcane Wraiths, as well as Felendren the Banished; they are located in the Falthrien Academy. Bring Felendren's Head to Lanthan Perilon on Sunstrider Isle.", progress = "Heed well this warning - Felendren the Banished is only a symptom of a much larger problem.  His demise will solve our immediate concerns, but all blood elves share the potential same fate as him if we let our addictions get the best of us.", completion = "Felendren's head... you are to be commended, <name>.  You've succeeded where others, like Felendren, have utterly failed.  Perhaps you are truly ready to be a contributing member of <race> society.\n\nYour success here means that you are capable of surviving the greater threats that lurk in Eversong... and believe me, there are plenty to face." }
WordHunterWoW_QuestEN[8336] = { title = "Fistful of Slivers", description = "It's a shame that we've lost control of many of the creatures here on the island.  This was once a tranquil place of study and research.  Now it's all we can do to keep from being attacked by our own creations!\n\nI'm going to offer you a chance to receive a magical boon in exchange for some collecting work on your part.  Bring me a stack of arcane slivers that are found on the mana-using creatures of Sunstrider Isle, and I will cast a spell on you that should aid your adventures on the isle.", objectives = "Collect 6 Arcane Slivers from any creature on the isle that uses mana, and then return to Arcanist Ithanas on Sunstrider Isle.", progress = "Many of the creatures here on the isle were at one point bound into non-aggression and complacency by our magical skills.  When the Scourge destroyed the Sunwell, our hold over these creatures shattered.  Arcane slivers are the remnants of the control we once had, and as such might be usable in fashioning a new device to aid us in regaining their control.\n\nBetter still, perhaps the slivers could be used to see what malaise the isle truly suffers under...", completion = "Splendid - these will do nicely.  I've been doing quite a bit of thinking on the current malaise Sunstrider Isle suffers under.  One possible course of action I had pondered was to collect these arcane slivers from the beasts on the isle.  In doing so, they could be experimented on; this would provide a potential source of culpability.\n\nAnyway, I will tend to the research.  Allow me to place this incantation on you.  I believe you'll make good use of it!" }
WordHunterWoW_QuestEN[8338] = { title = "Tainted Arcane Sliver", description = "You've found an odd sliver of crystallized mana on the corpse of the tainted arcane wraith.  The sliver is different than others you may have seen in that it is as dark and sinister-looking as the wraith you looted it from.  Just holding it gives you a sense of unnatural foreboding.\n\nArcanist Helion at the gazebo of the Sunspire on Sunstrider Isle just might be someone who would have a use for the sliver.", objectives = "Bring the Tainted Arcane Sliver to Arcanist Helion at the gazebo of the Sunspire on Sunstrider Isle.", progress = "From your demeanor, you seem to be on a matter of some urgency.  Is there something specific I can assist you with?", completion = "This is... most interesting.  And when I say interesting, I mean more disturbing than anything else.\n\nOur efforts to reassert control over the isle in the time following the destruction of the Sunwell have been a challenge.  I suspect that whatever foul source is corrupting the isle is at the heart of it all; this sliver may be of some aid in uncovering what's really going on.\n\nYou were wise to bring this to me, <name>.  Take this as compensation for your diligence.  Thank you." }
WordHunterWoW_QuestEN[8341] = { title = "Lords of the Council", description = "Lords of the Abyssal Council can only be summoned through the greater wind stones, and only the top ranking members of the Twilight's Council may speak to them.  But... I have found a way to upgrade your disguise and fool the Abyssal Lords!\n\nThe disguise calls for a ring of lordship, worn only by the highest members of the cult.  I will craft one for you if you can bring me large brilliant shards and abyssal signets.", objectives = "Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.", progress = "Do you have the shards and the signets, <name>?  I will need them to create the ring of lordship.", completion = "Thanks.  Just one moment and I'll have that ring ready for you...\n\nThere it is.  Now you're ready.\n\nBe sure to wear this ring, along with a medallion of station and the rest of the twilight trappings, when you activate a greater wind stone.  Do that, and the Abyssal Council will think you one of their servants.  Then, perhaps you can lure one into an ambush!" }
WordHunterWoW_QuestEN[8342] = { title = "Twilight Ring of Lordship", description = "", objectives = "<name>, if you plan to go after the Abyssal High Council again, then you'll need another Twilight ring of lordship.  Bring me more shards and signets and I'll make one for you.", progress = "<name>, if you plan to go after the Abyssal High Council again, then you'll need another Twilight ring of lordship.  Bring me more shards and signets and I'll make one for you.", completion = "Ah, I see your convictions are strong.  Not many will face that council of fiends!\n\nHere's your ring, <name>.  May your will, and your fortune, stand firm." }
WordHunterWoW_QuestEN[8343] = { title = "Goldleaf's Discovery", description = "<name>, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle.  We know that if anyone can do it, you can.\n\nMay fortune go with you, <name>.  Speak with Aurel when you are ready.", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.<name>, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle. We know that if anyone can do it, you can.\n\nMay fortune go with you, <name>. Speak with Aurel when you are ready.", completion = "What Huum says is true.  I believe I know how to summon a lord of the Abyssal Council!  Listen on, and I will explain..." }
WordHunterWoW_QuestEN[8344] = { title = "Windows to the Source", description = "Heed my words, young one - there is a taint about this island, and it is far more potent than the remnants of the Scourge.\n\nI believe there is a true demonic presence on the isle.\n\nWest of here are the spires of Falthrien Academy.  The arcane wraiths that infest it are a window to the source of demonic power.  You are to bring me the essences of tainted and untainted wraiths.\n\nIn exchange for your obedience, I'll teach you how to summon an imp companion - your first of many as a warlock.You will learn:", objectives = "Bring 4 Wraith Essences and 1 Tainted Wraith Essence to Summoner Teli'Larien at the Sunspire on Sunstrider Isle." }
WordHunterWoW_QuestEN[8345] = { title = "he Shrine of Dath'Remar", description = "Day after day I stand here, watching, waiting.  I've been accused of dwelling too much on our past, while my eyes look to the horizon.  But it is my firm belief that each visitor to this island should honor those who have sacrificed all so that they may continue to do so.\n\nDath'Remar Sunstrider was our first king.  He led us here from Kalimdor through the Maelstrom.\n\nSeek out his shrine to the west and do not return to me until you have read the plaque upon it in his honor.", objectives = "Read the plaque on the Shrine of Dath'Remar and then return to Well Watcher Solanian at the Sunspire on Sunstrider Isle.", completion = "Ah, <name> - thank you for sharing your experience at the Shrine of Dath'Remar.  First off, you should be commended for your sense of duty and respect - it will serve you well not only here, but in all of Azeroth as well.\n\nAs for the odd sensation, it is no doubt a contributing part of the taint that has befallen Sunstrider Isle.  We shall keep an eye on it; thank you for alerting us to it!" }
WordHunterWoW_QuestEN[8346] = { title = "hirst Unending", description = "If there is only one lesson you deign to remember from your time on Sunstrider Isle, let it be this - control your thirst for magic.  It is a thirst unending, <name> - what you absorb must be controlled and released via Arcane Torrent.  Failure is to become one of the Wretched... hopelessly addicted and insane.\n\nSeek out a mana wyrm and unleash your Arcane Torrent upon it.  Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.", objectives = "Use your Arcane Torrent racial ability on a Mana Wyrm, then return to Arcanist Helion.", completion = "You've done well today, <name>.  Your willingness to learn shows that you may very well rise above the unyielding cravings you must endure as a <race>.\n\nRest not on your laurels, young one, but instead seek to master what you have learned.  Only through diligence will we as a race survive.\n\nTake this - it may be of some use to you.  Go now, and bring glory once more to our people." }
WordHunterWoW_QuestEN[8347] = { title = "Aiding the Outrunners", description = "Magistrix Erona wanted you to head over to Silvermoon City in order to aid our reclamation efforts there... that is, once you had successfully addressed the situation at Falthrien Academy.  You did not disappoint us, {name}.\n\nOn your way to Falconwing Square, south of here, you should speak with Outrunner Alarion.  She's not far from the bridge.\n\nThe Outrunners take care of shuttling goods between here and the mainland, and since you've proven to be so resourceful, they could use your assistance.", objectives = "Speak with Outrunner Alarion near the bridge leading south of Sunstrider Isle.", completion = "Well hello there, <class>!  I heard that a resourceful young <race> formerly in the service of Magistrix Erona might be making their way down here to help us Outrunners out.  We certainly welcome the help, especially from someone who's proven to be so competent.\n\nI hope you're interested in running an errand or two for us." }
WordHunterWoW_QuestEN[8348] = { title = "Signet of the Dukes", description = "Huum tells me you've figured out how to summon the Abyssal Dukes!  That's quite an accomplishment.\n\nYou know what else would be quite the accomplishment?  Smashing up one of those things really good.  That'll cause an impression on their underlings, if you know what I mean.  Bring back its signet as proof of the deed.", objectives = "Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.", progress = "How did it go with the Abyssal Duke?  Did it hit hard?", completion = "I knew you were a tough <class> the minute I saw you walk into Cenarion Hold.  Keep it up!" }
WordHunterWoW_QuestEN[8349] = { title = "Bor Wildmane", description = "Now that you have a medallion and can summon an Abyssal Duke, speak with Bor Wildmane.  He will set you on a task against the Abyssal Council.\n\nGood luck, <name>.  And if you ever need more medallions, return to me.", objectives = "Speak with Bor Wildmane in Cenarion Hold.", completion = "Good to see you again, <class>!  So you had a medallion made?  Good -- you'll need that for your next quest..." }
WordHunterWoW_QuestEN[8350] = { title = "Completing the Delivery", description = "The death of another outrunner is a true tragedy, but it's a risk we all accept when we take the job.  Magistrix Erona at the Sunspire needs to get this package to the inn at Falconwing Square, and she needs it there as soon as possible.\n\nWe're short handed and I don't have anyone else available that can cover for us.\n\nI'm not going to lie to you; the path to Falconwing Square can be extremely dangerous if you leave the safety of Dawning Lane.  Do you feel up to the task, {name}?", objectives = "Deliver Erona's Package to Innkeeper Delaniel inside the inn at Falconwing Square in Eversong Woods.", progress = "Welcome to my inn, <class>.  Am I to understand that you have something for me?", completion = "Thank you, I do appreciate the prompt delivery.\n\nWhile you're here, please make yourself comfortable.  If you haven't done so already, feel free to get a hearthstone and bind yourself here.  Using a hearthstone will allow you to recall to an inn once every half-hour.  If you ever lose your hearthstone, simply return to any inn - an innkeeper will gladly get you a new one." }
WordHunterWoW_QuestEN[8351] = { title = "Bor Wishes to Speak", description = "Now that you can disguise yourself as a ruling member of the Twilight Council, I am certain Bor Wildmane will want to speak with you.  Go see him, and prepare yourself for a very difficult mission...", objectives = "Speak with Bor Wildmane in Cenarion Hold.", completion = "Yes, that's right, <name>.  I have a very tough task ahead..." }
WordHunterWoW_QuestEN[8352] = { title = "Scepter of the Council", description = "Huum and I were just talking about you.  He tells me you're just about ready to try your hand at fighting an Abyssal Lord!\n\nI must tell you this is a very dangerous endeavor.  You'd better bring backup.  And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force.  If your friends are as good as you, you might even defeat it!\n\nIf you do - and I'll want evidence, as always - I'll give you a truly great reward.", objectives = "Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.", progress = "Well, how did it go?  I'd do anything to leave my post and wrestle one of those things myself!", completion = "You... you did it!  You did it, <name>!  Here!  Take this.  It's the biggest chest we had lying around and I filled it with some of the best stuff we found." }
WordHunterWoW_QuestEN[8353] = { title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating on behalf of a child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Ironforge Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell <class>, are you up to the challenge or not?!  Time to earn your treat!", objectives = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!", progress = "I'm waiting...", completion = "Too funny!  Well done, <name>!  Here's your treat.\n\nHappy Hallow's End!" }
WordHunterWoW_QuestEN[8354] = { title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating on behalf of a child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Undercity Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell <class>, are you up to the challenge or not?!  Time to earn your treat!", objectives = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!", progress = "I'm waiting...", completion = "Too funny!  Well done, <name>!  Here's your treat.\n\nHappy Hallow's End!" }
WordHunterWoW_QuestEN[8355] = { title = "Incoming Gumdrop", description = "A trick-or-treater!  Huzzah!\n\nWell now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily.  I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, <class>!", objectives = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!", progress = "Well, go ahead now...", completion = "Woo-woo!  Well done, <name>!  Here's your treat.\n\nHappy Hallow's End!" }
WordHunterWoW_QuestEN[8356] = { title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong <man/woman>!\n\nWhen and only when you flex, I'll give you some tasty Stormwind Nougat.  It's a great Hallow's End treat.", objectives = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!", progress = "No candy until you flex for me, <name>...", completion = "You are truly mighty, haha!  Well done, and thanks for being such a good sport.  Here's your candy.\n\nHappy Hallow's End, <name>!" }
WordHunterWoW_QuestEN[8357] = { title = "Dancing for Marzipan", description = "Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", objectives = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!", progress = "You know how to dance, don't you?  Try by putting your right foot in... then your right foot out... your right foot in... shake it all about...", completion = "You're quite the dancing machine, <name>!\n\nHere's your treat for being such a good sport.  Happy Hallow's End, and give my best to your sick little friend!  I hope they get better soon." }
WordHunterWoW_QuestEN[8358] = { title = "Incoming Gumdrop", description = "A trick-or-treater!  Yeah mon!\n\nWell now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily.  I have a yummy Darkspear Gumdrop to give to the child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, <class>!", objectives = "Do a train emote at Kali Remik, and in exchange you'll receive a Darkspear Gumdrop!", progress = "Well, go ahead now...", completion = "Woo-woo!  Well done, <name>!  Here's your treat.\n\nHappy Hallow's End!" }
WordHunterWoW_QuestEN[8359] = { title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong <man/woman>!\n\nWhen and only when you flex, I'll give you some tasty Orgrimmar Nougat.  It's a great Hallow's End treat.", objectives = "Do a flex emote at Innkeeper Gryshka, and in exchange you'll receive Orgrimmar Nougat!", progress = "No candy until you flex for me, <name>...", completion = "You are truly mighty, haha!  Well done, and thanks for being such a good sport.  Here's your candy.\n\nHappy Hallow's End, <name>!" }
WordHunterWoW_QuestEN[8360] = { title = "Dancing for Marzipan", description = "Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", objectives = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!", progress = "You know how to dance, don't you?  Try by putting your right foot in... then your right foot out... your right foot in... shake it all about...", completion = "You're quite the dancing machine, <name>!\n\nHere's your treat for being such a good sport.  Happy Hallow's End, and give my best to your little friend!" }
WordHunterWoW_QuestEN[8361] = { title = "Abyssal Contacts", description = "We've seen the Twilight's Hammer cultists performing rituals to summon powerful elemental nobles.  We don't know if these are the beings the cultists worship or if they act as intermediaries to even more powerful forces.  One thing is for sure: they are receiving orders from these elementals.\n\nI want you to find a way to contact an Abyssal Templar and give it a proper beating!  Nothing throws the troops in disarray like taking out the chain of command.  Bring back proof while you're at it.", objectives = "Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.", progress = "Did you finish the job?", completion = "Hah!  You did it, <name>!  The Twilight's Hammer will soon be crushed!" }
WordHunterWoW_QuestEN[8362] = { title = "Abyssal Crests", description = "", objectives = "You've proved you can handle yourself in a fight, <name>.  Let's keep the pressure up on the Twilight's Hammer.  Go fight some more Abyssal Templars, I'll reward you with some of the stuff Huum and I have found in battle.", progress = "You've proved you can handle yourself in a fight, <name>.  Let's keep the pressure up on the Twilight's Hammer.  Go fight some more Abyssal Templars, I'll reward you with some of the stuff Huum and I have found in battle.", completion = "You've done well!  That's less Templars for me to worry about.\n\nHere you go, <name>.  Hope there's something useful in there for you." }
WordHunterWoW_QuestEN[8363] = { title = "Abyssal Signets", description = "", objectives = "" }
WordHunterWoW_QuestEN[8364] = { title = "Abyssal Scepters", description = "", objectives = "" }
WordHunterWoW_QuestEN[8365] = { title = "Pirate Hats Ahoy!", description = "You're the help the Cartel sent? I suppose you'll do. Listen carefully <class>. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part.\n\nSo here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?", objectives = "Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", progress = "Do you have all 20 hats? I don't believe you, let me see them. They better be in pristine condition!", completion = "Oh you're a darling, even if it did take you longer than I am accustomed to. This shipment should make me quite a bit of money once I've cleaned and personalized these hats. And seeing as I'm always willing to reward work that's well done, here's a little something for you. I suggest that you spend some of it on a bath sweetie." }
WordHunterWoW_QuestEN[8366] = { title = "Southsea Shakedown", description = "Argh! They want the impossible from me!\n\nThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace.\n\nOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for.\n\nYou'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks <name>, I'll owe you one!", objectives = "Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.", completion = "<name>! You are the man!!!\n\nI'm sure that the Cartel will ease up on me now that you've dealt with those Southsea scum. Let's see, what can I give you as a reward? How about a little coin and you choose from one of these for your trouble?" }
WordHunterWoW_QuestEN[8367] = { title = "For Great Honor", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance on every front!  For Honor!  For the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Mark of Honor from each battleground to a Horde Warbringer in any Horde capital city or Shattrath." }
WordHunterWoW_QuestEN[8368] = { title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[8369] = { title = "Invaders of Alterac Valley", description = "Listen up, <name>.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[8370] = { title = "Conquering Arathi Basin", description = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, <name>!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[8371] = { title = "Concerted Efforts", description = "We're not fighting isolated battles against the Horde anymore, <lad/lass>.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  <name>, come back to me after you've served against the Horde at all of our active battlegrounds.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Mark of Honor from each battleground to an Alliance Brigadier General in any Alliance Capital City, Dalaran or Shattrath." }
WordHunterWoW_QuestEN[8372] = { title = "Fight for Warsong Gulch", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, <name>!  For the Alliance!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[8373] = { title = "The Power of Pine", description = "The thing I hate the most about Hallow's End are the stink bombs the Forsaken use on Southshore.  Who knew that celebrating liberation would have to involve such a smelly mess?\n\nDuring Hallow's End, use this cleaner to remove any nasty stink bombs the Horde may drop here in the village.  It uses the power of pine to fight funky smells.\n\nDo your part to keep Southshore clean, and I'll give you some Hallow's End treats I'm sure you'll enjoy.  We have a deal?", objectives = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore. Return to Sergeant Hartman in Southshore when you're done.", completion = "Ah, it almost smells better around here already.  Almost.\n\nThanks to you, <name>, Southshore just might make it through another Hallow's End.  Here's your treats, with my thanks!  If you run out of candy, I think there's a gnome named Katrina Shimmerstar in Ironforge who can sell you more; she's only around during Hallow's End, I believe." }
WordHunterWoW_QuestEN[8374] = { title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[8375] = { title = "Remember Alterac Valley!", description = "Make no mistake about it, <name>.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory.\n\nYou see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced.\n\nLet us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, <class>, do your part in the battle for Alterac Valley.  For the Alliance!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[8376] = { title = "Armaments of War", description = "", objectives = "War comes, <name>, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n<Geologist Larksbane turns pale.>\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert." }
