WordHunterWoW_QuestEN[8728] = { title = "The Good News and The Bad News", description = "Well that took a little longer than expected. Now let me see what this ledger says.\n\n<Narain silently reads the ledger, periodically mumbling under his breath.>\n\n The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.", objectives = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", progress = "Arcanite buoys don't just make themselves, <name>. And NO, you cannot borrow some money.", completion = "A deal is a deal. I sure hope you know what you are getting yourself into, <name>. This is an awful lot of trouble to go through to do some fishing." }
WordHunterWoW_QuestEN[8729] = { title = "The Wrath of Neptulon", description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.", objectives = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", progress = "Time is running out, champion.", completion = "Well done, <name>. I will be able to reform the Scepter of the Shifting Sands soon." }
WordHunterWoW_QuestEN[8730] = { title = "Nefarius's Corruption", description = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!", objectives = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", progress = "Another of our heroes lost to the spawn of Deathwing. We will be cursed with this suffering forever...", completion = "Vaelastrasz's soul is at ease, champion. The Aspects all watch your progress with great interest. Know that you have powerful allies.\n\nI was commanded to grant you something to aid you in this struggle. Use it well..." }
WordHunterWoW_QuestEN[8731] = { title = "Field Duty", description = "Greetings, <name>.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Skullsplit's Orgrimmar Legion outside Hive'Regal.\n\nReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.\n\nOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.", objectives = "Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal. Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.\n\nNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.", progress = "You've completed your field duty, <name>?  Captain Skullsplit can be found outside of Hive'Regal.", completion = "I can tell that Krug has little use for paperwork.  He signed this in silithid blood!\n\nVery well, <name>.  I've prepared a set of tasks that should make good use of your skills as a <class>.\n\nWith the continued efforts of you and people like you, our enemy will soon be crushed!" }
WordHunterWoW_QuestEN[8732] = { title = "Field Duty Papers", description = "", objectives = "Field duty papers?  What manner of nonsense is this, <name>?", progress = "Field duty papers?  What manner of nonsense is this, <name>?", completion = "In the old days I would've marked your forehead with the creature's blood to mark your accomplishment here.  Thrall insists we comply with the Druids' requests.\n\nHere, take these papers and go back to Cenarion Hold.  I'm sure they will have suitable work for you." }
WordHunterWoW_QuestEN[8733] = { title = "Eranikus, Tyrant of the Dream", description = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.\n\nTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.\n\n<Malfurion sighs.>\n\nA fall from grace a thousand years in the making...", objectives = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", completion = "The wisp is silent except for a low humming sound. Oddly enough, it is able to communicate with you through thoughts." }
WordHunterWoW_QuestEN[8734] = { title = "Tyrande and Remulos", description = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.\n\nNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.\n\nWe all wish you great luck.", objectives = "Travel to the Moonglade and speak to Keeper Remulos.", completion = "It would be impossible to pull Eranikus from the Dream should he refuse. His intentions, however, require him to enter our world. He seeks to destroy the living manifestation of Malfurion. To do this successfully would mean an end to one of the most powerful allies of the Dream. The Nightmare would wholly consume all that would remain should Malfurion fall..." }
WordHunterWoW_QuestEN[8735] = { title = "The Nightmare's Corruption", description = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments.", objectives = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.", progress = "<Remulos is lost deep in thought.>", completion = "Are you prepared? Is the world prepared for what we are about to invoke? I do not know... I am bound by duty to Malfurion. Duty and honor..." }
WordHunterWoW_QuestEN[8736] = { title = "The Nightmare Manifests", description = "We must use restraint against Eranikus. We are to redeem him not destroy him.\n\nTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and your allies are our only hope.", objectives = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", completion = "He is redeemed, <name>. He now returns to the Dream to right what he alone has done wrong. Eranikus will be a powerful ally to Malfurion and my father.\n\nThese armaments are for you, <name>; given to me by Ysera herself. You would do well to make use of them in your battles against the Qiraji." }
WordHunterWoW_QuestEN[8737] = { title = "Azure Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Azure Templar and report to Bor Wildmane.", objectives = "Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing I in order to complete this quest.", progress = "Is your task done yet, <name>?", completion = "Good job, <name>.  Here's your next assignment." }
WordHunterWoW_QuestEN[8738] = { title = "Hive'Regal Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Landion has been watching the silithid movements at Hive'Regal for several days now.  Find him and obtain a written report.  We need to be able to act on that information as soon as possible, <name>.", objectives = "Contact Cenarion Scout Landion inside Hive'Regal and return the Hive'Regal Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VII in order to complete this quest.", progress = "You'll find Scout Landion inside Hive'Regal.  Hurry, <name>!  Time is of the essence.", completion = "Your efforts are greatly appreciated, <name>.  I'll read these scouting reports right away, feel free to go over your next assignment." }
WordHunterWoW_QuestEN[8739] = { title = "Hive'Ashi Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Jalia has been watching the silithid movements at Hive'Ashi for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, <name>.", objectives = "Contact Cenarion Scout Jalia inside Hive'Ashi and return the Hive'Ashi Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VIII in order to complete this quest.", progress = "You'll find Scout Jalia inside Hive'Ashi.  Hurry, <name>!  Time is of the essence.", completion = "Your efforts are greatly appreciated, <name>.  I'll read these scouting reports right away, feel free to go over your next assignment." }
WordHunterWoW_QuestEN[8740] = { title = "Twilight Marauders", description = "Bands of mounted Twilight's Hammer cultists have been spotted riding outside the reach of our forces in Cenarion Hold, picking off our smaller patrols and caravans.\n\nFind and defeat the twilight marauders along with their leader, a terrible warrior by the name of Morna.  Report to Windcaller Proudhorn after completing the task.", objectives = "Slay Twilight Marauder Morna and 2 Twilight Marauders. Report to Windcaller Proudhorn when your task is finished. You must also bring Tactical Task Briefing IX in order to complete this quest.", progress = "Is your task done yet, <name>?", completion = "Well done, <name>.  The twilight marauders were inflicting an unacceptable number of casualties on our patrols.  Here's your next assignment." }
WordHunterWoW_QuestEN[8741] = { title = "The Champion Returns", description = "The keeper awaits your return, <name>. Take the green scepter shard to Anachronos at the Caverns of Time.", objectives = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.", progress = "<Anachronos nods.>", completion = "Your deeds will be known to all, champion. They will sing your praises from Orgrimmar to the far reaches of the South Seas. All will know of the champion of the Bronze Flight, <name>." }
WordHunterWoW_QuestEN[8742] = { title = "The Might of Kalimdor", description = "", objectives = "A thousand years has passed and just as it was fated, one stands before me. One who shall lead their people to a new age.\n\nThe Old God trembles, <name>. Oh yes, it fears your faith. Shatter the prophecy of C'Thun.\n\nIt knows you come, champion - and with you comes the might of Kalimdor. You have only to let me know when you are prepared and I shall grant you the Scepter of the Shifting Sands.", progress = "A thousand years has passed and just as it was fated, one stands before me. One who shall lead their people to a new age.\n\nThe Old God trembles, <name>. Oh yes, it fears your faith. Shatter the prophecy of C'Thun.\n\nIt knows you come, champion - and with you comes the might of Kalimdor. You have only to let me know when you are prepared and I shall grant you the Scepter of the Shifting Sands.", completion = "The Scepter of the Shifting Sands is whole once more, <name>.\n\nIt must be you who uses the scepter. It must be you who heralds the next age of your people./n/nYou must wait for the armies of the Horde and the Alliance to arrive in Silithus before you may ring the Scarab Gong." }
WordHunterWoW_QuestEN[8743] = { title = "Bang a Gong!", description = "", objectives = "The Scarab Gong looms ominously before you. Steel yourself, <name>; for once The Scarab Gong is rung, the gates of Ahn'Qiraj will be opened.\n\nFrom the slackened maw of the beast can only come chaos and destruction. Defend your people!", progress = "The Scarab Gong looms ominously before you. Steel yourself, <name>; for once The Scarab Gong is rung, the gates of Ahn'Qiraj will be opened.\n\nFrom the slackened maw of the beast can only come chaos and destruction. Defend your people!", completion = "From the ground near the gong springs a special crystal. Perhaps favor from the Brood." }
WordHunterWoW_QuestEN[8744] = { title = "A Carefully Wrapped Present", description = "", objectives = "The tag on this present reads:\n\nTo <name>,\n\nMay your feast of Great-Winter be merry and bright!" }
WordHunterWoW_QuestEN[8745] = { title = "Treasure of the Timeless One", description = "", objectives = "Greetings, champion. I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.\n\nI have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove. May it aid you in your battles against C'Thun." }
WordHunterWoW_QuestEN[8746] = { title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We believe he was carried off by that dastardly Abominable Greench, hiding out in Hillsbrad Foothills.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen, defeat his captors, and return him to us!", objectives = "Rescue Metzen the Reindeer from his captors near Growless Cave in the Hillsbrad Foothills.", progress = "<name>!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of what those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, <name>.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!" }
WordHunterWoW_QuestEN[8747] = { title = "The Path of the Protector", description = "", objectives = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", progress = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", completion = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind." }
WordHunterWoW_QuestEN[8748] = { title = "The Path of the Protector", description = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.\n", objectives = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, <name>. May you never stray from the path of the protector!" }
WordHunterWoW_QuestEN[8749] = { title = "The Path of the Protector", description = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", objectives = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", progress = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, <name>. May you never stray from the path of the protector!" }
WordHunterWoW_QuestEN[8750] = { title = "The Path of the Protector", description = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.\n", objectives = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, <name>. May you never stray from the path of the protector!" }
WordHunterWoW_QuestEN[8751] = { title = "The Protector of Kalimdor", description = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", objectives = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Protector of Kalimdor! Rise and be recognized!" }
WordHunterWoW_QuestEN[8752] = { title = "The Path of the Conqueror", description = "", objectives = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the conqueror will greatly enhance your physical attacks.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", progress = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the conqueror will greatly enhance your physical attacks.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", completion = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the conqueror will greatly enhance your physical attacks.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind." }
