WordHunterWoW_QuestEN[8756] = { title = "The Qiraji Conqueror", description = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", objectives = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Qiraji Conqueror! Rise and be recognized!" }
WordHunterWoW_QuestEN[8757] = { title = "The Path of the Invoker", description = "", objectives = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the invoker will greatly enhance your magical and natural abilities.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", progress = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the invoker will greatly enhance your magical and natural abilities.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", completion = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the invoker will greatly enhance your magical and natural abilities.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind." }
