WordHunterWoW_QuestEN[8761] = { title = "The Grand Invoker", description = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.\n", objectives = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Grand Invoker! Rise and be recognized!" }
WordHunterWoW_QuestEN[8762] = { title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We believe he was carried off by that dastardly Abominable Greench, hiding out in Hillsbrad Foothills.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen, defeat his captors, and return him to us!", objectives = "Rescue Metzen the Reindeer from his captors near Growless Cave in Hillsbrad Foothills.", progress = "<name>!  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of what those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Greatfather Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, <name>.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!" }
WordHunterWoW_QuestEN[8763] = { title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", objectives = "Bring 1 Deeprock Salt and 5 gold coins to any Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!" }
WordHunterWoW_QuestEN[8764] = { title = "The Changing of Paths - Protector No More", description = "", objectives = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", progress = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", completion = "Be well, <name>. If you change your mind, I shall be here to assist you." }
