WordHunterWoW_QuestEN[8767] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[8768] = { title = "A Gaily Wrapped Present", description = "", objectives = "This festively-wrapped present has your name on it.\n\nWait, did it just move?" }
WordHunterWoW_QuestEN[8769] = { title = "A Ticking Present", description = "", objectives = "Have a joyous Feast of Great-Winter from your friends at Smokywood Pastures." }
WordHunterWoW_QuestEN[8770] = { title = "Target: Hive'Ashi Defenders", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi defenders.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Slay 30 Hive'Ashi Defenders and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing I in order to complete this quest.", progress = "You have something to tell me, <class>?", completion = "Excellent work, <name>.  Your diligence is as noteworthy as always." }
WordHunterWoW_QuestEN[8771] = { title = "Target: Hive'Ashi Sandstalkers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi sandstalkers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Slay 30 Hive'Ashi Sandstalkers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing II in order to complete this quest.", progress = "You have something to tell me, <class>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Ashi has been noted." }
WordHunterWoW_QuestEN[8772] = { title = "Target: Hive'Zora Waywatchers", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora waywatchers.  Report back to Commander Mar'alith after completing your task.", objectives = "Slay 30 Hive'Zora Waywatchers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VI in order to complete this quest.", progress = "You have something to tell me, <class>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Zora has been noted." }
WordHunterWoW_QuestEN[8773] = { title = "Target: Hive'Zora Reavers", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora reavers.  Report back to Commander Mar'alith after completing your task.", objectives = "Slay 30 Hive'Zora Reavers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing IV in order to complete this quest.", progress = "You have something to tell me, <class>?", completion = "I've heard good things about your part in the Hive'Zora attack.  Keep up the good work and victory will soon be ours." }
WordHunterWoW_QuestEN[8774] = { title = "Target: Hive'Regal Ambushers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the Hive'Regal ambushers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Kill 30 Hive'Regal Ambushers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VIII in order to complete this quest.", progress = "You wish to tell me something, <name>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Regal has been noted." }
WordHunterWoW_QuestEN[8775] = { title = "Target: Hive'Regal Spitfires", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the airborne Hive'Regal spitfires.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Kill 30 Hive'Regal Spitfires and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing IX in order to complete this quest.", progress = "You wish to tell me something, <name>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Regal has been noted." }
WordHunterWoW_QuestEN[8776] = { title = "Target: Hive'Regal Slavemakers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the Hive'Regal slavemakers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Kill 30 Hive'Regal Slavemakers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing X in order to complete this quest.", progress = "You wish to tell me something, <name>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Regal has been noted." }
WordHunterWoW_QuestEN[8777] = { title = "Target: Hive'Regal Burrowers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of Hive'Regal burrowers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Kill 30 Hive'Regal Burrowers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing XI in order to complete this quest.", progress = "You wish to tell me something, <name>?", completion = "Excellent work, <name>.  Your part in the attack on Hive'Regal has been noted." }
WordHunterWoW_QuestEN[8778] = { title = "The Ironforge Brigade Needs Explosives!", description = "The Ironforge Brigade has put in an unusual request for highly... volatile... components.  Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.You will receive:", objectives = "Bring 6 Oils of Immolation, 5 Goblin Rocket Fuel and 10 Dense Blasting Powder to Arcanist Nozzlespring near Hive'Zora in Silithus. You must also bring Logistics Task Briefing IV in order to complete this quest." }
WordHunterWoW_QuestEN[8779] = { title = "Scrying Materials", description = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.", objectives = "Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing V in order to complete this quest.", progress = "You have something for me, <name>?", completion = "Why, yes... these will be of tremendous aid!  These materials are awfully hard to come by in the desert, <name>.  Thank you." }
WordHunterWoW_QuestEN[8780] = { title = "Armor Kits for the Field", description = "The Ironforge Brigade's supply of armor kits in the battlefield is running dangerously low.  Obtain a batch and deliver them to Janela Stouthammer at the Ironforge Brigade's outpost outside Hive'Zora.", objectives = "Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Janela Stouthammer at the Ironforge Brigade Outpost near Hive'Zora in Silithus. You must also bring Logistics Task Briefing VII in order to complete this quest.", progress = "You have something for me, <name>?", completion = "Thanks, I'll hand these out to the lads." }
WordHunterWoW_QuestEN[8781] = { title = "Arms for the Field", description = "The Ironforge Brigade has been a worthy ally in our fight in Silithus.  Unfortunately, many of their supplies were lost on their way here.  Procure a batch of weapons and deliver them to Janela Stouthammer near Hive'Zora.", objectives = "Bring 2 Moonsteel Broadswords to Janela Stouthammer at the Ironforge Brigade Outpost outside of Hive'Zora. You must also bring Logistics Task Briefing VI in order to complete this quest.", progress = "You have something for me, <name>?", completion = "Oh, excellent!  I won't have to hear complaints about dull blades anymore.  Thank you, <name>." }
WordHunterWoW_QuestEN[8782] = { title = "Uniform Supplies", description = "The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.", objectives = "Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing VIII in order to complete this quest.", progress = "You have something for me, <name>?", completion = "Ah, we were in need of these.  Your work is appreciated, <name>." }
WordHunterWoW_QuestEN[8783] = { title = "Extraordinary Materials", description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.", objectives = "Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing IX in order to complete this quest.", progress = "You have something for me, <name>?", completion = "Ah, yes.  These materials are of excellent quality.  Thank you, <name>." }
WordHunterWoW_QuestEN[8784] = { title = "Secrets of the Qiraji", description = "You have discovered an ancient Qiraji artifact! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.", objectives = "Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple.", progress = "You're glowing! I know what that means...", completion = "An exceptional find, <name>. Simply marvelous! This will definitely give us some insight into our enemy's twisted minds." }
WordHunterWoW_QuestEN[8785] = { title = "The Orgrimmar Legion Needs Mojo!", description = "The Orgrimmar Legion has put in a request for several unusual ingredients.  Given their current performance in Silithus, we'd like to comply with their request as soon as possible.  Gather the materials and bring them to the troll called Shai.", objectives = "Bring 6 Powerful Mojo, 6 Flasks of Big Mojo and 8 Oils of Immolation to Shadow Priestess Shai near Hive'Regal in Silithus. You must also bring Logistics Task Briefing IV in order to complete this quest.", progress = "Do you have my materials, <name>?", completion = "Ah, yes.  Just what I needed!  I'll make a special concoction with this.  The silithid won't like it one bit!" }
WordHunterWoW_QuestEN[8786] = { title = "Arms for the Field", description = "The Orgrimmar Legion has put in a request for additional weapons that we haven't been able to provide at the moment.  Obtain the weapons they've requested and bring them to Merok Longstride outside of Hive'Regal.You will receive:", objectives = "Bring 3 Massive Iron Axes to Merok Longstride at the Orgrimmar Legion camp outside of Hive'Regal. You must also bring Logistics Task Briefing VI in order to complete this quest." }
WordHunterWoW_QuestEN[8787] = { title = "Armor Kits for the Field", description = "The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid us in our cause.  Their supplies of armor kits were somehow lost in the trip.  Obtain a batch of armor kits and deliver them to Merok Longstride at the location of the Orgrimmar Legion camp.You will receive:", objectives = "Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Merok Longstride near Hive'Regal. You must also bring Logistics Task Briefing VII in order to complete this quest." }
WordHunterWoW_QuestEN[8788] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[8789] = { title = "Imperial Qiraji Armaments", description = "We have not sat idly by for a millennium, <name>.\n\nWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.\n\nWeaknesses exist and we know how to use those weaknesses to our advantage.\n\nFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.", objectives = "Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ingots.", progress = "Seek out what I requested. You will become greater than the sum of your parts, champion.", completion = "Infused with Elementium, these weapons will cut through the Qiraji and their God with incredible ease." }
WordHunterWoW_QuestEN[8790] = { title = "Imperial Qiraji Regalia", description = "Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.", objectives = "Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ingots.", progress = "You will strike them down and free us of these bonds.", completion = "Use the item well, <name>. Let them feel the pain that they so dearly wish to inflict upon others." }
WordHunterWoW_QuestEN[8791] = { title = "The Fall of Ossirian", description = "A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.", objectives = "Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.", progress = "Ah, <name>, you have returned! And in one piece, I might add. What news do you bring from Ahn'Qiraj?", completion = "I offer you my highest commendation and your choice of an item of power, <name>. You have done the people of Kalimdor a great service." }
WordHunterWoW_QuestEN[8792] = { title = "he Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, <class>? Will you help out with the vital preparations?Upon completion of this quest you will gain:", objectives = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, <class>? Will you help out with the vital preparations?Upon completion of this quest you will gain:" }
