WordHunterWoW_QuestEN[8798] = { title = "A Yeti of Your Own", description = "", objectives = "Say! You know what?! You're an engineer too! So, since you helped me teach my friends a lesson, I'm going to teach you how to make your very own mechanical yeti! Now the fun can go on forever and ever, and you can scare whoever you want! Provided that you can scare up the components to make it that is.\n\nWhat do you say, <name>? Do you want to learn the secret to making a mechanical yeti?" }
WordHunterWoW_QuestEN[8799] = { title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", objectives = "Bring 1 Deeprock Salt and 5 gold coins to the Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!" }
WordHunterWoW_QuestEN[8800] = { title = "Cenarion Battlegear", description = "As you complete the tasks you're assigned in the war you'll want to talk to Vargus, the blacksmith.  Show him any badges you've earned along the way. He'll provide you with gear to match your level of commitment to our cause.", objectives = "Talk to Vargus at Cenarion Hold in Silithus.", completion = "Kaldon sent you?  Very well, let's see what we can do for you." }
WordHunterWoW_QuestEN[8801] = { title = "C'Thun's Legacy", description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed.\n\nAs you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in the next chamber.", objectives = "Take the Eye of C'Thun to Caelestrasz in the Temple of Ahn'Qiraj.", progress = "<Caelastrasz kneels before you.>\n\nLord <name>, you have freed us of its grasp.", completion = "We will leave this place on our own, Lord <name> - once we are certain that the evil within has been wholly destroyed. Your journey of legend is almost at an end." }
WordHunterWoW_QuestEN[8802] = { title = "The Savior of Kalimdor", description = "To the Caverns of Time you go, Lord {name}. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.\n", objectives = "Take the Eye of C'Thun to Anachronos at the Caverns of Time.", progress = "Lord <name>! It is over...", completion = "The Master has left these for you, champion. From the timeless cache: A collection of artifacts spanning thousands of years - the choice is yours." }
WordHunterWoW_QuestEN[8803] = { title = "A Festive Gift", description = "", objectives = "The note on this present reads:\n\nTo <name>,\n\nIn hoping this will help you spread warm tidings and holiday cheer to all of Azeroth.\n\nFrom Greatfather Winter" }
WordHunterWoW_QuestEN[8804] = { title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.You will receive:", objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus. You must also bring Logistics Task Briefing I in order to complete this quest." }
WordHunterWoW_QuestEN[8805] = { title = "Boots for the Guard", description = "The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.You will receive:", objectives = "Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing II in order to complete this quest." }
WordHunterWoW_QuestEN[8806] = { title = "Grinding Stones for the Guard", description = "The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.You will receive:", objectives = "Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing III in order to complete this quest." }
WordHunterWoW_QuestEN[8807] = { title = "Scrying Materials", description = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.You will receive:", objectives = "Bring 2 Large Brilliant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing V in order to complete this quest." }
WordHunterWoW_QuestEN[8808] = { title = "Uniform Supplies", description = "The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.You will receive:", objectives = "Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing VIII in order to complete this quest." }
WordHunterWoW_QuestEN[8809] = { title = "Extraordinary Materials", description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.You will receive:", objectives = "Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing IX in order to complete this quest." }
WordHunterWoW_QuestEN[8810] = { title = "Bandages for the Field", description = "Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.You will receive:", objectives = "Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing X in order to complete this quest." }
