WordHunterWoW_QuestEN[8883] = { title = "Valadar Starsong", description = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!", objectives = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.", completion = "<name>, welcome to Nighthaven, host of the Lunar Festival!  Although our village is normally remote and sequestered from the peoples of Azeroth, during this time of celebration we open our arms and hearts to all.\n\nEnjoy your visit, <name>, and speak with me or my sister again when ready." }
WordHunterWoW_QuestEN[8884] = { title = "Fish Heads, Fish Heads...", description = "Greetings, {class}.  Take a look toward the shore; what do you see?  That's right, our beach... our Tranquil Shore, has been infested with the malignancy known as the murloc.\n\nThis blight will not stand!\n\nI have a task for you.  If you feel that you're up to it, I would have their heads!  Let us see if we can put a dent in their numbers so large that, if they have any sense at all, they will return to the murky depths from which they sprang!", objectives = "Collect 8 Grimscale Murloc Heads. Return them to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", progress = "We rangers of the Farstrider Retreat are dedicated to setting right the damage that has been wreaked upon our fair lands.  We will go to any length to do so.\n\nI trust that you have returned with the murloc heads I tasked you to gather?", completion = "A job well done, <class>.  By the smell of it, I'd say you returned all that I asked for, and possibly more.  I'm sure we can find some use for these, in a stew, or somesuch.\n\nAlas, it does not appear that your efforts have done the trick; the murlocs are not in retreat.  This calls for more direct action!" }
